na Morninglight", tgt="Laurna Morninglight"}, [166]={npc="Laurna Morninglight", tgt="Laurna Morninglight", desc="Wirk Geringes Heilen und Machtwort: Seelenstärke auf die verwundeten Schildwachen. Belohnung: Stoffrüstung."}, [167]={hint="Sucht die Schildwache Shaya und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morninglight in Dolanaar zurück.", desc="Wirk Geringes Heilen und Machtwort: Seelenstärke auf die verwundeten Schildwachen. Belohnung: Stoffrüstung."}, [168]={npc="Laurna Morninglight", tgt="Laurna Morninglight", desc="Wirk Geringes Heilen und Machtwort: Seelenstärke auf die verwundeten Schildwachen. Belohnung: Stoffrüstung."}}},
    ["01-7"] = {tips={{k="交通", text="Startgebiet der Skyborne. Allianz und Horde teilen sich die Startquests der Insel und trennen sich erst beim Verlassen der Insel nach Fraktion.", s={{"Startgebiet der Skyborne. Allianz und Horde teilen sich die Startquests der Insel und trennen sich erst beim Verlassen der Insel nach Fraktion.", {race={"天裔"}}}}}}, steps={[1]={npc="Dalia die Sammlerin", tgt="Ailee Farheart"}, [2]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [3]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [4]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [5]={hint="Tötet 8 junge Vuldren im Thendalhain."}, [6]={hint="Tötet 8 lästige Zirrusfliegen im Thendalhain."}, [7]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [8]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [9]={npc="Halaan Hawk-Eye", tgt="Halaan Hawk-Eye"}, [10]={npc="Halaan Hawk-Eye", tgt="Halaan Hawk-Eye"}, [11]={npc="Myriaal Mistwake", tgt="Myriaal Mistwake"}, [12]={hint="Springt von der Spitze des Wachturms im Thendalhain und verlangsamt Euren Fall mit Eurer Fähigkeit \"Luftwandeln\".", desc="Setz beim Sprung in Richtung Zirrusfliegenkönigin dein Skyborne-Volksfähigkeit ein."}, [14]={hint="Vernichtet die Zirrusfliegenkönigin im Thendalhain."}, [15]={npc="Falorne Fallwind", tgt="Elatrell Featherlight"}, [16]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [17]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [18]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [19]={npc="Falorne Fallwind", tgt="Falorne Fallwind"}, [20]={npc="Rorian der Tagsucher", tgt="Rorian der Tagsucher"}, [21]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [22]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [23]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [24]={npc="Ailee Farheart", tgt="Rorian der Tagsucher"}, [25]={npc="Ailee Farheart", tgt="Rorian der Tagsucher", tag="Im Spiel prüfen"}, [26]={npc="Dorii Brightwhisper", tgt="Dorii Brightwhisper"}, [27]={npc="Windf