    ["01-9"] = {tips={{k="交通", text="Menschen nehmen in Sturmwind die Tiefenbahn nach Eisenschmiede. Nachtelfen fahren mit dem Schiff nach Sturmwind und dann mit der Bahn. Skyborne lassen diese Station aus: In Station 8 gehen sie von Dalaran durch das Portal nach Sturmwind und fahren dann mit dem Schiff zur Dunkelküste.", s={{"Menschen nehmen in Sturmwind die Tiefenbahn nach Eisenschmiede", {race={"Human"}}}, {"Nachtelfen fahren mit dem Schiff nach Sturmwind und dann mit der Bahn", {race={"NightElf"}}}, {"Skyborne lassen diese Station aus: In Station 8 gehen sie von Dalaran durch das Portal nach Sturmwind und fahren dann mit dem Schiff zur Dunkelküste", {race={"天裔"}}}}}}, steps={[1]={npc="Rudra Amberstill", tgt="Rudra Amberstill", tag="Optional, Gruppe empfohlen"}, [2]={hint="Rudra Amberstill möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf die Widder-Ranch bringt.", tag="Optional, Gruppe empfohlen"}, [3]={npc="Rudra Amberstill", tgt="Rudra Amberstill", tag="Optional, Gruppe empfohlen"}, [4]={npc="Erdseher Farsen", tgt="Erdseher Farsen"}, [5]={npc="Erdseher Farsen", tgt="Erdseher Farsen"}, [6]={npc="Erdseher Farsen", tgt="Erdseher Farsen"}, [7]={npc="Senator Mehr Stonehallow", tgt="Senator Mehr Stonehallow"}, [8]={npc="Großknecht Stonebrow", tgt="Großknecht Stonebrow"}, [9]={hint="Tötet 10 Spione der Dunkeleisenzwerge in Dun Morogh."}, [10]={npc="Dunkeleisenkarte", npcObj=true, desc="Rechtsklicke Dunkeleisenkarte im Rucksack, um die Quest anzunehmen."}, [11]={hint="Tötet für Senator Mehr Stonehallow im Gol'Bolar Steinbruch 10 Knochenknacker der Felsenkiefer."}, [12]={npc="Großknecht Stonebrow", tgt="Großknecht Stonebrow"}, [13]={npc="Senator Mehr Stonehallow", tgt="Senator Mehr Stonehallow"}, [14]={npc="Erdseher Farsen", tgt="Erdseher Farsen"}, [15]={npc="Erdseher Farsen", tgt="Erdseher Farsen"}, [16]={npc="Pilot Hammerfoot", tgt="Pilot Hammerfoot"}, [17]={npc="Eine Zwergenleiche", npcObj=true}, [18]={npc="Eine Zwergenleiche", npcObj=true}, [1