    ["02-11"] = {steps={[1]={node="Stormwind"}, [2]={text="Verlass Sturmwind und folge der Straße durch den Wald von Elwynn nach Westen, geh durch Goldhain und über die Brücke nach Westfall und folge dann der Hauptstraße nach Süden bis zur Späherkuppe.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [3]={npc="Deputy Rainer", tgt="Deputy Rainer"}, [4]={npc="Bauer Furlbrow", tgt="Bauer Furlbrow"}, [5]={npc="Verna Furlbrow", tgt="Verna Furlbrow"}, [6]={npc="Verna Furlbrow", tgt="Verna Furlbrow"}, [7]={hint="Verna Furlbrow in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt.", tag="Optional"}, [8]={npc="Bauer Saldean", tgt="Bauer Saldean"}, [9]={npc="Salma Saldean", tgt="Salma Saldean"}, [10]={npc="Ozwin Ironsprocket", tgt="Ozwin Ironsprocket"}, [11]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [12]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [13]={nodeA="{a:108}"}, [14]={npc="Späher Galiaan", tgt="Späher Galiaan"}, [15]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [16]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [17]={hint="Nutzt das Set für Brunnenwasserproben, um Proben aus den Brunnen auf Jansens Hof und Molsens Hof zu sammeln."}, [18]={hint="Bauer Furlbrow möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen.", desc="Mit passendem Kamerawinkel kannst du es von außen plündern."}, [19]={hint="Alba Fairmoon möchtet, dass Ihr 7 Murlockiemen von Longshore an der Küste von Westfall sammelt."}, [20]={npc="Bauer Furlbrow", tgt="Bauer Furlbrow"}, [21]={hint="Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet."}, [22]={npc="Verna Furlbrow", tgt="Verna Furlbrow"}, [23]={npc="Bauer Saldean", tgt="Bauer Saldean"}, [24]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [25]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [26]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [27]={hint="Tötet 4 Koboldbuddler im Jangoschacht und 6 Minenarbeiter der Flusspfoten im Goldküstensteinbruch."}, [28]={hint="Gryan Stoutmantle möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt."}, [29]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [30]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [31]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Optional"}, [32]={hint="Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan."}, [33]={hint="Ozwin Ironsprocket auf Saldeans Hof möchte, dass Ihr ihm 14 Golemisofedern und 5 Gyrostabilisatoren für Erntearbeiter bringt."}, [34]={hint="Gryan Stoutmantle möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [35]={npc="Alba Fairmoon", tgt="Alba Fairmoon"}, [36]={npc="Späher Galiaan", tgt="Späher Galiaan"}, [37]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Optional"}, [38]={npc="Ozwin Ironsprocket", tgt="Ozwin Ironsprocket"}, [39]={}, [40]={npc="Baros Alexston", tgt="Baros Alexston"}, [41]={npc="Baros Alexston", tgt="Baros Alexston"}, [42]={npc="Brandur Ironhammer", tgt="Brandur Ironhammer"}, [43]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [44]={npc="Foliant der Offenbarung", npcObj=true, desc="Rechtsklicke Foliant der Offenbarung im Rucksack, um die Quest anzunehmen."}, [45]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [46]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [47]={npc="John Turner", tgt="John Turner"}, [48]={npc="John Turner", tgt="John Turner"}, [49]={npc="John Turner", tgt="John Turner", desc="Hast du weniger als 10 Leinenstoff, kauf welchen im Auktionshaus. Meist ist er billig."}, [50]={npc="John Turner", tgt="John Turner"}, [51]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [52]={npc="Tiza Battleforge", tgt="Tiza Battleforge"}, [53]={npc="Muiredon Battleforge", tgt="Muiredon Battleforg