    ["05-d1"] = {name="Die Halle der Thanen", entrance="Eisenschmiede 27.63, 47.83", pickup="Nimm auf dem Weg durch Dun Morogh und Loch Modan zuerst die Quests vor dem Dungeon an; kurz vor dem Eingang musst du nicht extra zurück. Skyborne überspringen 01-Station 9: Geh beim ersten Besuch in Eisenschmiede nach Osten nach Dun Morogh zu Erdseher Farsen, erledige Farsens Wacht, Erstickt sie im Keim und Karte des Untergrunds und kehr dann nach Eisenschmiede zurück. Willst du den Umweg nicht machen, überspring Eindringlinge in der Altstadt von Ironforge.", pickupS={{"Nimm auf dem Weg durch Dun Morogh und Loch Modan zuerst die Quests vor dem Dungeon an; kurz vor dem Eingang musst du nicht extra zurück"}, {"Skyborne überspringen 01-Station 9: Geh beim ersten Besuch in Eisenschmiede nach Osten nach Dun Morogh zu Erdseher Farsen, erledige Farsens Wacht, Erstickt sie im Keim und Karte des Untergrunds und kehr dann nach Eisenschmiede zurück", {race={"天裔"}}}, {"Willst du den Umweg nicht machen, überspring Eindringlinge in der Altstadt von Ironforge"}}, steps={[1]={npc="Dunkeleisenkarte", npcObj=true, tag="Dungeon-Vorquest"}, [2]={npc="Erdseher Farsen", tgt="Erdseher Farsen", tag="Dungeon-Vorquest"}, [3]={npc="Erdseher Farsen", tgt="Erdseher Farsen"}, [4]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [5]={npc="Thom Filch", tgt="Thom Filch"}, [6]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [7]={text="Eingang: Die Halle der Thanen"}, [8]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [9]={hint="Tötet 15 wütende Erscheinungen und 10 gepeinigte Seelen, und bettet den Geist von Anvilmar zur Ruhe."}, [10]={hint="Sammelt 8 zwergische Erbstücke in der Halle der Thanen."}, [11]={hint="Betretet die Halle der Thanen unter der Altstadt von Ironforge und besorgt den Kopf von Durgen Dirgehammer."}, [12]={npc="Treaty of Understanding", npcObj=true, desc="Der Endboss setzt bei etwa 35 % Gesundheit Furcht ein. Räum zuerst die Begleiter weg und zieh den Boss dann in den vorherigen Raum. Neben dem Questgeber ist ein Hebel. Zieh ihn, um die Tür zu öffnen, und lauf direkt hinaus."}, [13]={npc="Thom Filch", tgt="Thom Filch"}, [14]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [15]={npc="König Magni Bronzebeard", tgt="König Magni Bronzebeard"}, [16]={npc="König Magni Bronzebeard", tgt="König Magni Bronzebeard"}}},
    ["02-12"] = {steps={[1]={npc="Gryth Thurden", tgt="Gryth Thurden"}, [2]={node="Ironforge"}, [4]={text="Verlass Eisenschmiede und folge der Straße nach Osten, geh durch den Tunnel im östlichen Pass nach Loch Modan und folge dann dem Weg nach Nordosten bis Thelsamar.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [5]={nodeA="{a:144}"}, [6]={hint="Gebirgsjäger Gravelgaw im südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher tötet und ihm anschließend Bericht erstattet."}, [7]={npc="Gebirgsjäger Gravelgaw", tgt="Gebirgsjäger Gravelgaw"}, [8]={npc="Gebirgsjäger Wallbang", tgt="Gebirgsjäger Wallbang"}, [9]={hint="Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben."}, [10]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [11]={npc="Brock Stoneseeker", tgt="Brock Stoneseeker"}, [12]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [13]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [14]={npc="Ausgrabungsleiter Ironband", tgt="Ausgrabungsleiter Ironband"}, [15]={npc="Daryl der Jüngling", tgt="Daryl der Jüngling"}, [16]={hint="Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück."}, [17]={npc="Daryl der Jüngling", tgt="Daryl der Jüngling"}, [18]={npc="Daryl der Jüngling", tgt="Daryl der Jüngling"}, [19]={hint="Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück."}, [20]={npc="Daryl der Jüngling", tgt="Daryl der Jüngling"}, [21]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [22]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [23]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [24]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [25]={hint="Findet und besiegt den Krokilisken Dolchzahn und holt Mareks Messer zurück."}, [26]={hint="Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Ironheart in der Weitschreiter-Lodge."}, [27]={hint="Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:"}, [28]={hint="Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet."}, [29]={npc="Chefingenieur Hinderweir VII.", tgt="Chefingenieur Hinderweir VII."}, [30]={npc="Verdächtiges Fass", npcObj=true}, [31]={npc="Verdächtiges Fass", npcObj=true}, [32]={npc="Chefingenieur Hinderweir VII.", tgt="Chefingenieur Hinderweir VII."}, [33]={npc="Gebirgsjäger Stormpike", tgt="Gebirgsjäger Stormpike", desc="Folge vom Damm der Nordstraße nach Westen bis zum Außenposten am Pass."}, [34]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [35]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [36]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [37]={hint="Bringt Magmar Fellhew 8 verzierte Steingötzen."}, [38]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [39]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [40]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [41]={npc="Gebirgsjäger Wallbang", tgt="Gebirgsjäger Wallbang"}, [42]={}, [43]={npc="Argos Nightwhisper", tgt="Argos Nightwhisper"}, [44]={npc="Narm Faulk", tgt="Narm Faulk"}, [45]={npc="Narm Faulk", tgt="Narm Faulk"}, [46]={hint="Beschafft ein Dunkeleisenmanuskript von den Dunkeleisenzwergen beim Helmsbedsee und kehrt zu Muiredon Battleforge in Ironforge zurück."}, [47]={npc="Muiredon Battleforge", tgt="Muiredon Battleforge"}, [48]={npc="Muiredon Battleforge", tgt="Muiredon Battleforge", desc="Gib die Quest ab, um Erlösung zu lernen."}, [49]={npc="Tiza Battleforge", tgt="Tiza Battleforge", desc="Gib die Quest ab, um Erlösung zu lernen."}, [50]={npc="Elanaria", tgt="Elanaria"}, [51]={npc="Elanaria", tgt="Elanaria"}, [52]={npc="Mathiel", tgt="Mathiel"}, [53]={npc="Mathiel", tgt="Mathiel", desc="Belohnung: eine Waffe aus Elunit."}, [54]={npc="Mathiel", tgt="Mathiel", desc="Belohnung: eine Waffe aus Elunit."}, [55]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Schließ „Körper und Herz\" am Moonkinstein bei Auberdine ab, kehr dann nach Darnassus zurück, gib ab und lerne Bärengestalt."}, [56]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [57]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [58]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [59]={hint="Benutzt das leere Gefäß bei Cliffspring Falls und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.", desc="Nimm in Nachthafen den Flug nur für Druiden nach Rut'theran und flieg dann nach Auberdine."}, [60]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong"}, [61]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Sammle Erdwurzel und Lunarfungus an der Dunkelküste und gib sie in Auberdine ab."}, [62]={hint="Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nightsong in Auberdine, damit sie eine Heilsalbe machen kann.", desc="Sammle Erdwurzel und Lunarfungus an der Dunkelküste und gib sie in Auberdine ab."}, [63]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Sammle Erdwurzel und Lunarfungus an der Dunkelküste und gib sie in Auberdine ab."}, [64]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Heile die kranken Hirsche an der Dunkelküste mit dem Heilmittel."}, [65]={hint="Benutzt die Tier-Heilsalbe bei 10 kranken Wildtieren rund um Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass krankes Wild südlich des Cliffspring, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo Ashenvale beginnt, aufgetaucht ist.", desc="Heile die kranken Hirsche an der Dunkelküste mit dem Heilmittel."}, [66]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Benutze nach der Heilung von 10 Hirschen „Teleportieren: Moonglade\", um zum Abgeben zurückzukehren."}, [67]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Gib die Quest ab, um Vergiftung heilen zu lernen."}, [68]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Gib die Quest ab, um Gift heilen zu lernen. Nimm in Nachthafen den Flug nur für Druiden nach Rut'theran und geh dort durch das Portal im Dorf nach Darnassus."}, [69]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [70]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [71]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Finde das Schrein-Schmuckstück am Grund des Elune'ara-Sees."}, [72]={hint="Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.", desc="Finde das Schrein-Schmuckstück am Grund des Elune'ara-Sees."}, [73]={npc="Tajarri", tgt="Tajarri", desc="Finde das Schrein-Schmuckstück am Grund des Elune'ara-Sees."}, [74]={npc="Tajarri", tgt="Tajarri", desc="Die zwei seltsamen verschlossenen Truhen enthalten je eine Amulett-Hälfte: Eine liegt auf dem Meeresgrund nördlich von Auberdine in der Dunkelküste, die andere auf dem Meeresgrund vor der Nordwestküste von Westfall."}, [75]={hint="Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.", desc="Nimm in Nachthafen den Flug nur für Druiden nach Rut'theran, flieg nach Auberdine und schwimm nach Norden zur verschlossenen Truhe auf dem Meeresgrund. Fahr dann mit dem Schiff von Auberdine nach Sturmwind, flieg zur Späherkuppe und tauch im Nordwesten vor der Küste hinab, um die andere verschlossene Truhe zu öffnen."}, [76]={text="Benutze mit beiden Hälften „Teleportieren: Moonglade\", um zurückzukehren, und setze die Amulett-Hälften in der Nähe des Schreins von Remulos zusammen."}, [77]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [78]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Gib die Quest ab, um Wassergestalt zu lernen."}, [79]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Gib die Quest ab, um Wassergestalt zu lernen. Nimm in Nachthafen den Flug nur für Druiden nach Rut'theran und geh dort durch das Portal im Dorf nach Darnassus."}}},
    ["02-13"] = {steps={[1]={npc="Gubber Blump", tgt="Gubber Blump"}, [2]={npc="GESUCHT: Gurgelbacke!", npcObj=true}, [3]={npc="Archäologin Hollee", tgt="Archäologin Hollee"}, [4]={npc="Archäologin Hollee", tgt="Archäologin Hollee"}, [5]={npc="Thundris Windwirker", tgt="Thundris Windwirker"}, [6]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [7]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [8]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [9]={npc="Terenthis", tgt="Terenthis"}, [10]={npc="Terenthis", tgt="Terenthis"}, [11]={npc="Geheimnisvoller roter Kristall", npcObj=true}, [12]={npc="Geheimnisvoller roter Kristall", npcObj=true}, [13]={npc="Asterion", tgt="Asterion"}, [14]={npc="Gestrandete Meereskreatur", npcObj=true}, [15]={hint="Beschafft die Schließkassette der SILBERMORGEN und die Schließkassette der NEBELSCHLEIER für Gorbold Steelhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes."}, [16]={npc="Dröhnkiste 411", npcObj=true}, [17]={npc="Dröhnkiste 411", npcObj=true}, [18]={npc="Gestrandete Meeresschildkröte", npcObj=true}, [19]={text="Folge der Straße bis zu diesem Punkt.", desc="Töte ab jetzt unterwegs alle Mondpirscherwichte und Tollwütigen Distelbären."}, [20]={text="Folge der Straße bis zu diesem Punkt."}, [21]={hint="Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe."}, [22]={hint="Sammelt 6 feine Krebsbrocken für Gubber Blump in Auberdine."}, [23]={npc="Gestrandete Meeresschildkröte", npcObj=true}, [24]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [25]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [26]={hint="Sammelt 4 abgenutzte Pergamentfetzen für Balthule Shadowstrike in der Nähe des Turms von Althalaxx."}, [27]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [28]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [29]={hint="Befreit den Wald von 20 tollwütigen Distelbären und kehrt dann zu Tharnariun Treetender in Dunkelküste zurück."}, [30]={hint="Sammelt 6 Mondpirscherfangzähne und baut sie in Dröhnkiste 323 ein."}, [31]={hint="Bringt Barithras Moonshade in Auberdine 5 Schorfstänglinge und 1 Todeskappe."}, [32]={npc="Dröhnkiste 323", npcObj=true}, [33]={npc="Dröhnkiste 323", npcObj=true}, [34]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [35]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [36]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [37]={npc="Thundris Windwirker", tgt="Thundris Windwirker"}, [38]={npc="Thundris Windwirker", tgt="Thundris Windwirker"}, [39]={npc="Schildwache Glynda Nal'Shea", tgt="Schildwache Glynda Nal'Shea"}, [40]={npc="Barithras Moonshade", tgt="Barithras Moonshade", desc="Füll die Leere Säuberungsschale am Mondbrunnen."}, [41]={npc="Barithras Moonshade", tgt="Barithras Moonshade"}, [42]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [43]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [44]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [45]={npc="Gubber Blump", tgt="Gubber Blump"}, [46]={npc="Gestrandete Meereskreatur", npcObj=true}, [47]={npc="Gestrandete Meereskreatur", npcObj=true, desc="Das Ereignis startet nur in der Nähe des Lagerfeuers. Erledige es jetzt oder später, wenn die Route wieder vorbeiführt."}, [48]={npc="Gestrandete Meeresschildkröte", npcObj=true}, [49]={npc="Gestrandete Meeresschildkröte", npcObj=true}, [50]={npc="Gestrandete Meereskreatur", npcObj=true}, [51]={text="Folge der Straße bis zu diesem Punkt."}, [52]={npc="Schildwache Aynasha", tgt="Schildwache Aynasha", desc="Töte auf dem Weg zur nächsten Quest jeden Mondpirscherpatriarchen (Jungtiere und Matriarchin kommen mit)."}, [53]={hint="Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten in Ashenvale."}, [54]={npc="Onu", tgt="Onu"}, [55]={npc="Onu", tgt="Onu"}, [56]={npc="Wahrsageschale", npcObj=true, desc="Geh zu 39.2, 86.9 und benutze das Fläschchen von Onu, um es auf den Boden zu stellen."}, [57]={npc="Wahrsageschale", npcObj=true}, [58]={npc="Twilight-Foliant", npcObj=true}, [59]={npc="Twilight-Foliant", npcObj=true}, [60]={npc="Twilight-Foliant", npcObj=true}, [61]={hint="Erbeutet ein unvergleichliches Auge von einem Jünger oder Schläger des Twilight-Hammers an der Meistergleve in Dunkelküste und findet in Auberdine jemanden, der bereit ist, es an sich zu nehmen."}, [62]={npc="Therylune", tgt="Therylune", desc="Eskortquest: In der Gruppe erst annehmen, wenn alle gleich weit sind, und automatisches Annehmen ausschalten."}, [63]={hint="Verhelft Therylune zur Flucht und teilt dann Therysil beim Schrein von Aessina mit, dass ihre Schwester in Sicherheit ist."}, [64]={npc="Buch: Die Macht in der Tiefe", npcObj=true, tag="Optional", desc="Rechtsklicke Buch: Die Macht in der Tiefe im Rucksack, um die Quest anzunehmen. Gegner in der Grube lassen selten „Buch: Die Macht in der Tiefe\" fallen. Nur annehmen, wenn es droppt."}, [65]={npc="Ausgrabungsleiter Remtravel", tgt="Ausgrabungsleiter Remtravel", desc="Eskortquest: In der Gruppe erst annehmen, wenn alle gleich weit sind, und automatisches Annehmen ausschalten. Lass Ausgrabungsleiter Remtravel vorlaufen und kämpfe nur gegen Gegner, die ihn zuerst angreifen."}, [66]={npc="Ausgrabungsleiter Remtravel", tgt="Ausgrabungsleiter Remtravel"}, [67]={hint="Beschützt Ausgrabungsleiter Remtravel, während er nach dem rätselhaften Fossil sucht, und kehrt dann zur Archäologin Hollee in Auberdine zurück."}, [68]={npc="Dröhnkiste 525", npcObj=true}, [69]={hint="Sucht 5 feine Mondpirscherpelze und bringt sie Terenthis in Auberdine."}, [70]={npc="Onu", tgt="Onu"}, [71]={npc="Arbal", tgt="Arbal"}, [72]={npc="Onu", tgt="Onu"}, [73]={hint="Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.", desc="Es kommen mehrere Wellen Murlocs, je 2-3 pro Welle. Zieh den letzten Murloc jeder Welle vom Lagerfeuer weg, bevor du ihn tötest, iss und trink und hol dann die nächste Welle. Oder such eine Gruppe."}, [74]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [75]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [76]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [77]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [78]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [79]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [80]={npc="Schildwache Glynda Nal'Shea", tgt="Schildwache Glynda Nal'Shea"}, [81]={npc="Archäologin Hollee", tgt="Archäologin Hollee"}, [82]={npc="Archäologin Hollee", tgt="Archäologin Hollee"}, [83]={npc="Thundris Windwirker", tgt="Thundris Windwirker"}, [84]={npc="Terenthis", tgt="Terenthis"}, [85]={npc="Terenthis", tgt="Terenthis"}, [87]={desc="Ist Rut'theran nicht auf deiner Flugkarte, nimm wie die anderen Völker das Schiff."}, [88]={npc="Nessa Shadowsong", tgt="Nessa Shadowsong"}, [89]={text="Geh in Rut'theran durch das Portal nach Darnassus."}, [90]={npc="Chefarchäologe Greywhisker", tgt="Chefarchäologe Greywhisker"}, [91]={npc="Chefarchäologe Greywhisker", tgt="Chefarchäologe Greywhisker"}, [92]={text="Geh in Darnassus durch das Portal zurück nach Rut'theran."}, [93]={nodeA="{a:702}"}, [95]={hint="Sucht und tötet die Höhlenmutter."}, [96]={hint="Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine."}, [97]={hint="Bringt 6 Mathystra-Relikte zu Onu in den Hain der Uralten."}, [98]={hint="Tötet für Arbal im Hain der Uralten 12 Myrmidonen der Sturmschuppen, 8 Zauberinnen der Sturmschuppen und 6 Krieger der Sturmschuppen."}, [99]={hint="Findet eine Tierbändigerin der Sturmschuppen, tötet sie und nehmt ihre Rute der Tiefenherrschaft an Euch."}, [100]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [101]={text="Lässt sich Lakeshire wählen, flieg einfach; sonst verlässt du Sturmwind auf der Elwynner Straße nach Osten ins Rotkammgebirge und schaltest in Lakeshire nebenbei den Greifenpunkt frei."}, [102]={npc="Lucius", tgt="Lucius"}, [103]={npc="Lucius", tgt="Lucius", desc="Wende Schlossknacken auf die Kiste bei Althers Mühle an."}, [104]={hint="Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain.", desc="Wende Schlossknacken auf die Kiste bei Althers Mühle an."}, [105]={npc="Lucius", tgt="Lucius", desc="Wende Schlossknacken auf die Kiste bei Althers Mühle an."}, [106]={npc="Arantir", tgt="Arantir", tag="Optional"}, [107]={hint="Bringt die Hörner von Nez'ra zu Arantir nach Seenhain.", tag="Optional"}, [108]={npc="Arantir", tgt="Arantir", tag="Optional"}, [109]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw"}, [110]={npc="Agentin Kearnen", tgt="Agentin Kearnen"}, [111]={npc="Agentin Kearnen", tgt="Agentin Kearnen", desc="Stiehl den versiegelten Brief aus dem Turm der Defias in Westfall. Lerne danach Gifte."}, [112]={hint="Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Stormwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen.", desc="Stiehl den versiegelten Brief aus dem Turm der Defias in Westfall. Lerne danach Gifte."}, [113]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", desc="Stiehl den versiegelten Brief aus dem Turm der Defias in Westfall. Lerne danach Gifte."}, [114]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", tag="Optional"}, [115]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [116]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [117]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [118]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [119]={hint="Bringt Doc Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, junger Herr.", tag="Optional"}, [120]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Optional"}, [121]={npc="Hohepriesterin Laurena", tgt="Hohepriesterin Laurena", desc="Lerne Rückkopplung."}, [122]={npc="Hohepriesterin Laurena", tgt="Hohepriesterin Laurena", desc="Lerne Rückkopplung."}, [123]={npc="Hohepriesterin Laurena", tgt="Hohepriesterin Laurena", desc="Nimm sie in Sturmwind an, gib sie in Eisenschmiede ab und lerne Furchtzauberschutz."}, [124]={npc="Hohepriester Rohan", tgt="Hohepriester Rohan", desc="Nimm sie in Sturmwind an, gib sie in Eisenschmiede ab und lerne Furchtzauberschutz."}, [125]={npc="Hohepriesterin Laurena", tgt="Hohepriesterin Laurena", desc="Nimm sie in Sturmwind an und gib sie in Dun Morogh ab."}, [126]={npc="Hohepriesterin Mims", tgt="Hohepriesterin Mims", desc="Nimm sie in Sturmwind an und gib sie in Dun Morogh ab."}, [127]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="Die Taverne Zum Blauen Eremiten ist im Magierviertel von Sturmwind."}, [128]={hint="Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Cannon. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum.", desc="Die Taverne Zum Blauen Eremiten ist im Magierviertel von Sturmwind."}, [129]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="Die Taverne Zum Blauen Eremiten ist im Magierviertel von Sturmwind."}, [130]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="Gib 10 Leinenstoff und 6 Aufgeladene Rissedelsteine ab. Die Edelsteine gibt es im Auktionshaus."}, [131]={npc="Wynne Larson", tgt="Wynne Larson", desc="Gib 10 Leinenstoff und 6 Aufgeladene Rissedelsteine ab. Die Edelsteine gibt es im Auktionshaus."}, [132]={npc="Wynne Larson", tgt="Wynne Larson", desc="Belohnung: Managewirkte Robe."}, [133]={npc="Wynne Larson", tgt="Wynne Larson", desc="Belohnung: Managewirkte Robe."}, [134]={npc="Gakin der Dunkelbinder", tgt="Gakin der Dunkelbinder"}, [135]={npc="Takar der Seher", tgt="Takar der Seher", desc="Fahr vom Hafen von Sturmwind mit dem Schiff nach Auberdine, folge der Küste der Dunkelküste nach Süden bis ins Eschental, geh dann von Osten über den Mor'shan-Wall ins Brachland und weiter nach Süden zu Takar. Das Wegkreuz und Camp Taurajo sind Horde-Stützpunkte; umgeh sie."}, [136]={npc="Takar der Seher", tgt="Takar der Seher"}, [137]={npc="Takar der Seher", tgt="Takar der Seher"}, [138]={hint="Holt das Herzholz aus Ashenvale und bringt es zu Gakin dem Dunkelbinder im Magierviertel von Stormwind.", desc="Erledige zuerst die Gegner am Baum und klick dann den Baum des Cenarius an, um Herzholz zu erhalten."}, [139]={hint="Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Stormwind."}, [140]={npc="Gakin der Dunkelbinder", tgt="Gakin der Dunkelbinder", desc="Benutze nach dem Eschental deinen Ruhestein nach Sturmwind. Hat der Ruhestein Abklingzeit, geh nach Norden zurück nach Auberdine und nimm das Schiff nach Sturmwind."}, [141]={npc="Gakin der Dunkelbinder", tgt="Gakin der Dunkelbinder"}, [142]={npc="Gakin der Dunkelbinder", tgt="Gakin der Dunkelbinder", desc="Benutze ihn am Beschwörungskreis neben Gakin dem Dunkelbinder und besiege den beschworenen Sukkubus."}, [143]={hint="Beschwört mit Hilfe des Herzholzkerns einen Sukkubus, unterwerft ihn und bringt dann den Herzholzkern zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", desc="Benutze ihn am Beschwörungskreis neben Gakin dem Dunkelbinder und besiege den beschworenen Sukkubus."}, [144]={npc="Gakin der Dunkelbinder", tgt="Gakin der Dunkelbinder", desc="Benutze ihn am Beschwörungskreis neben Gakin dem Dunkelbinder und besiege den beschworenen Sukkubus."}, [145]={npc="Gakin der Dunkelbinder", tgt="Gakin der Dunkelbinder"}, [146]={hint="Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück."}, [147]={npc="Gakin der Dunkelbinder", tgt="Gakin der Dunkelbinder"}, [148]={}}},
    ["05-d2"] = {name="Die Ruinen von Lordaeron", entrance="Unterstadt 72.41, 11.37", steps={[1]={text="Optional und weit entfernt: Der Eingang liegt in den Ruinen von Lordaeron über Unterstadt, du musst also durch Horde-Gebiet. Nimm das Schiff von Auberdine nach Menethil, steig in Süderstade aus und entdecke den Flugpunkt, dann geh nach Norden durch das Vorgebirge von Hillsbrad und den Silberwald nach Tirisfal. Benutze nach dem Dungeon deinen Ruhestein nach Sturmwind und steig bei 02-Station 14 wieder ein.", tag="Optional, Im Spiel prüfen"}, [2]={}, [3]={npc="Blutverschmiertes Insigne", npcObj=true, desc="Rechtsklicke Blutverschmiertes Insigne im Rucksack, um die Quest anzunehmen."}, [4]={text="Eingang: Die Ruinen von Lordaeron"}, [5]={hint="Sammelt 10 blutverschmierte Insignien und bringt sie zu General Marcus Jonathan in Stormwind."}, [6]={npc="Wappen von Lordaeron", npcObj=true, desc="Rechtsklicke Wappen von Lordaeron im Rucksack, um die Quest anzunehmen."}, [7]={npc="Blood-Stained Parchment", npcObj=true}, [8]={}, [9]={npc="Waisenmatrone Nightingale", tgt="Waisenmatrone Nightingale"}, [10]={npc="Lady Dena Kennedy", tgt="Lady Dena Kennedy"}, [11]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan"}}},
    ["02-14"] = {steps={[1]={text="Folge von Sturmwind aus der Straße durch den Wald von Elwynn nach Osten ins Rotkammgebirge und bleib auf der Straße bis Seenhain.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [2]={npc="Theocritus", tgt="Theocritus"}, [3]={npc="Wache Parker", tgt="Wache Parker"}, [4]={}, [5]={npc="Wache Parker", tgt="Wache Parker", desc="Wache Parker steht an der Kreuzung der Hauptstraße westlich des Rotkammgebirge, die zum Wald von Elwynn führt."}, [6]={npc="Darcy", tgt="Darcy"}, [7]={npc="Wiley der Schwarze", tgt="Wiley der Schwarze"}, [8]={npc="Wiley der Schwarze", tgt="Wiley der Schwarze"}, [9]={npc="Dockmeister Baren", tgt="Dockmeister Baren"}, [10]={npc="Dockmeister Baren", tgt="Dockmeister Baren"}, [11]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [12]={npc="Verner Osgood", tgt="Verner Osgood"}, [13]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [14]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [15]={npc="Deputy Feldon", tgt="Deputy Feldon"}, [16]={nodeA="{a:69}"}, [18]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [19]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [21]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan"}, [22]={npc="General Marcus Jonathan", tgt="General Marcus Jonathan"}, [23]={npc="Schmied Argus", tgt="Schmied Argus"}, [24]={npc="Schmied Argus", tgt="Schmied Argus"}, [25]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw"}, [26]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw"}, [28]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [29]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [30]={hint="Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Stoutmantle."}, [31]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [32]={npc="Der Verräter der Defias", tgt="Der Verräter der Defias"}, [33]={hint="Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias E