    ["05-d6"] = {name="Excavation Site: Wetlands", nameA="{a:16732}", entrance="Sumpfland 47.79, 56.16", pickup="Nimm beim Eintreffen im Eschental (1. Besuch) zuerst Suche nach Caitlin an (benötigt Stufe 24). Auch Suche nach Songblade im Rotkammgebirge benötigt Stufe 24; als du vorher dort durchkamst, warst du meist noch nicht hoch genug.", pickupS={{"Nimm beim Eintreffen im Eschental (1"}, {"Besuch) zuerst Suche nach Caitlin an (benötigt Stufe 24)"}, {"Auch Suche nach Songblade im Rotkammgebirge benötigt Stufe 24; als du vorher dort durchkamst, warst du meist noch nicht hoch genug"}}, steps={[1]={npc="Llana", tgt="Llana", desc="Benötigt Stufe 24. Eschental, 1. Besuch: Erst annehmen, wenn du Stufe 24 hast."}, [2]={npc="Dorin Songblade", tgt="Dorin Songblade", tag="Optional", desc="Benötigt Stufe 24. Als du vorher durch das Rotkammgebirge kamst, warst du noch nicht hoch genug; überspring sie und geh nicht extra zurück."}, [3]={npc="Caitlin Grassman", tgt="Caitlin Grassman"}, [4]={text="Eingang: Excavation Site: Wetlands"}, [5]={npc="Caitlin Grassman", tgt="Caitlin Grassman"}}},
