    ["03-27"] = {steps={[1]={npc="Elling Trias", tgt="Elling Trias"}, [2]={npc="Elling Trias", tgt="Elling Trias"}, [3]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [4]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [5]={hint="Besiegt Dashel Stonefist in Stormwind."}, [6]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [7]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [8]={npc="Elling Trias", tgt="Elling Trias"}, [9]={npc="Elling Trias", tgt="Elling Trias"}, [10]={text="Geh in Sturmwind zum Zwergendistrikt und nimm die Tiefenbahn nach Eisenschmiede."}, [11]={npc="Großsteinmetz Marblesten", tgt="Großsteinmetz Marblesten"}, [12]={npc="Großsteinmetz Marblesten", tgt="Großsteinmetz Marblesten"}, [13]={npc="König Magni Bronzebeard", tgt="König Magni Bronzebeard"}, [14]={npc="Ausgrabungsleiter Stormpike", tgt="Ausgrabungsleiter Stormpike"}, [15]={npc="Ausgrabungsleiter Stormpike", tgt="Ausgrabungsleiter Stormpike"}, [16]={npc="Ausgrabungsleiter Stormpike", tgt="Ausgrabungsleiter Stormpike"}, [17]={npc="Ausgrabungsleiter Stormpike", tgt="Ausgrabungsleiter Stormpike"}, [18]={npc="Lago Blackwrench", tgt="Lago Blackwrench"}, [19]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Flieg von Eisenschmiede nach Beutebucht (Umstieg in Sturmwind) und fahr dann mit dem Schiff nach Ratschet."}, [20]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [21]={npc="Krom Stoutarm", tgt="Krom Stoutarm", desc="Fahr in Ratschet mit dem Schiff nach Beutebucht und flieg dann nach Eisenschmiede."}, [22]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [23]={hint="Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Krom Stoutarm in Ironforge.", desc="Flieg von Eisenschmiede nach Süderstade und auf dem Rückweg wieder nach Eisenschmiede."}, [24]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [25]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [26]={hint="Bringt den rekonstruierten Folianten und 3 Kanalisierungsruten zu Strahad Farsan in Ratchet.", desc="Flieg von Eisenschmiede nach