    ["03-28"] = {steps={[2]={npc="Schildwache Melyria Frostschatten", tgt="Schildwache Melyria Frostschatten"}, [3]={npc="Illiyana", tgt="Illiyana"}, [4]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [5]={text="Folge der Straße bis zu diesem Punkt."}, [6]={text="Folge der Straße bis zu diesem Punkt."}, [7]={hint="Begebt Euch ins heulende Tal, studiert den Folianten von Mel'Thandris und kehrt dann zur Schildwache Melyria Frostshadow beim Schrein von Aessina zurück.", desc="Geh durch die Höhle zum Buch. Man zieht leicht zu viele Gegner, und mit dem Rare-Mob dort wird es schwerer."}, [8]={text="Folge der Straße bis zu diesem Punkt."}, [9]={hint="Holt von dem Schattendickichtorakel einen gefallenen Mondstein und bringt ihn Pelturas in Astranaar."}, [10]={text="Folge der Straße bis zu diesem Punkt."}, [11]={hint="Befreit die Hochgeborenenseelen in Night Run und Satyrnaar und kehrt zu Delgren dem Läuterer in Maestras Posten zurück."}, [12]={npc="Anilia", tgt="Anilia"}, [13]={npc="Anilia", tgt="Anilia"}, [14]={hint="Tötet Geltharis und bringt Illiyana beim Schrein von Aessina den Zweig des Cenarius."}, [15]={npc="Kayneth Stillwind", tgt="Kayneth Stillwind"}, [16]={npc="Maseara Herbstmond", tgt="Maseara Herbstmond"}, [17]={hint="Maseara Herbstmond möchte, dass Ihr westlich von Forest Song unter den Satyrnaardämonen sucht. Meldet bei Eurer Rückkehr alle Hinweise auf ihren Mann Kurothel."}, [18]={npc="Maseara Herbstmond", tgt="Maseara Herbstmond"}, [19]={nodeA="{a:3137}"}, [21]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [22]={npc="Schildwache Melyria Frostschatten", tgt="Schildwache Melyria Frostschatten"}, [23]={npc="Schildwache Melyria Frostschatten", tgt="Schildwache Melyria Frostschatten", tag="Optional"}, [24]={npc="Illiyana", tgt="Illiyana"}, [25]={npc="Delgren der Läuterer", tgt="Delgren der Läuterer"}}},
    ["03-29"] = {steps={[1]={tag="Optional", desc="Der Abschnitt in Darnassus bringt wenig EP. Überspring ihn, wenn du es eilig hast."}, [2]={text="Geh in Rut'theran durch das Portal nach Darnassus.", tag="Optional"}, [3]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [4]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [5]={hint="Durchsucht Velindes Truhe nach ihrem Tagebuch und bringt es zusammen mit dem Schlüssel nach Darnassus zu Thyn'tel Bladeweaver.", tag="Optional"}, [6]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [7]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Optional"}, [8]={text="Geh in Darnassus durch das Portal zurück nach Rut'theran.", tag="Optional"}, [9]={text="Hast du die optionalen Quests in Darnassus gemacht, flieg von Rut'theran nach Ratschet (Umstieg in Auberdine und an der Talrendisspitze); wenn nicht, flieg von Astranaar (Umstieg an der Talrendisspitze). Folge der Hauptstraße nach Süden, umgeh Camp Taurajo und nimm den Großen Aufzug hinab in die Tausend Nadeln. Nur wenn beide Punkte nicht entdeckt sind, geh über den Mor'shan-Wall."}, [10]={text="Folge der Straße bis zu diesem Punkt."}, [11]={nodeA="{a:489}"}, [12]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [13]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [14]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [15]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [16]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [17]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [18]={npc="Pozzik", tgt="Pozzik"}, [19]={npc="Rennstreckenleiter Zherin", tgt="Rennstreckenleiter Zherin"}, [20]={hint="Beschafft 10 hohle Geierknochen für Pozzik in der schimmernden Ebene."}, [21]={hint="Tötet 10 Salzsteinbasilisken, 10 Salzsteinkristallhäute und 6 Salzsteinstarrer für Rennsteckenleiter Zherin in der schimmernden Ebene."}, [22]={hint="Bringt Wizzle Brassbolts in der schimmernden Ebene 9 gehärt