    ["03-30"] = {name="Arathihochland", steps={[1]={desc="Ist Die Zuflucht nicht freigeschaltet, flieg nach Menethil, folge der Straße durch das Sumpfland nach Nordosten, überquere den Thandol-Übergang ins Arathihochland und folge dann der Straße bis zur Zuflucht."}, [2]={npc="Captain Nials", tgt="Captain Nials"}, [3]={npc="Captain Nials", tgt="Captain Nials", desc="Gib bei Demar Brant in Burg Farholde in den Flusslanden ab; du kommst bei der nächsten Station dorthin."}, [4]={npc="Steckbriefbrett", npcObj=true, tag="Optional"}, [5]={npc="Steckbriefbrett", npcObj=true, tag="Optional"}, [6]={npc="Skuerto", tgt="Skuerto"}, [7]={npc="Lehrling Kryten", tgt="Lehrling Kryten"}, [8]={npc="Splitter von Myzrael", npcObj=true}, [9]={hint="Sammelt 12 Körner von Myzrael und bringt sie zu den regenbogenfarbenen Splittern in der Schlucht der Trockenstoppel."}, [10]={npc="Regenbogenfarbene Splitter", npcObj=true}, [11]={desc="Leveln bis etwa drei Viertel von Stufe 36."}, [12]={npc="Regenbogenfarbene Splitter", npcObj=true}, [13]={hint="Holt den brennenden Schlüssel, den Wappenschlüssel und den donnernden Schlüssel vom Stein der westlichen Bindung, dem Stein der östlichen Bindung und dem Stein der äußeren Bindung."}, [14]={npc="Quae", tgt="Quae"}, [15]={npc="Quae", tgt="Quae"}, [16]={hint="Sucht für Lehrling Kryten bei der Zuflucht 10 Hauer der Witherbark, 4 Medizinbeutel der Witherbark und 1 Schattenjägermesser.", desc="Achte auf den patrouillierenden Kurier der Verlassenen."}, [17]={npc="Lehrling Kryten", tgt="Lehrling Kryten"}, [18]={npc="Skuerto", tgt="Skuerto"}, [19]={hint="Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht."}, [21]={npc="Skuerto", tgt="Skuerto"}, [22]={npc="Skuerto", tgt="Skuerto", tag="Optional"}, [23]={hint="Tötet 10 Straßenräuber des Syndikats und 6 Söldner des Syndikats."}, [24]={npc="Captain Nials", tgt="Captain Nials"}, [25]={npc="Captain Nials", tgt="Captain Nials", tag="Optional"}, [26]={npc="Stein der inneren Bindung", 