    ["05-d8"] = {name="Das Scharlachrote Kloster", entrance="Tirisfal 82.60, 33.80", pickup="Nimm die Quests für den Dungeon schon bei Sumpfland (2. Besuch) an, dann musst du vorher nicht extra zurück.", pickupS={{"Nimm die Quests für den Dungeon schon bei Sumpfland (2"}, {"Besuch) an, dann musst du vorher nicht extra zurück"}}, steps={[1]={npc="Bilbliothekarin Mae Paledust", tgt="Bilbliothekarin Mae Paledust"}, [2]={desc="Du steigst in Eisenschmiede um."}, [3]={text="Geh von Southshore nach Norden durch die Vorgebirge von Hillsbrad und das Alteracgebirge, durch die Westliche Pestländer nach Westen nach Tirisfal und folge der Straße zum Scharlachroten Kloster in der Nordostecke.", tag="Im Spiel prüfen"}, [4]={text="Eingang: Das Scharlachrote Kloster"}, [5]={}, [6]={text="Geh in Sturmwind zum Zwergendistrikt und nimm die Tiefenbahn nach Eisenschmiede."}, [7]={npc="Bilbliothekarin Mae Paledust", tgt="Bilbliothekarin Mae Paledust", tag="Optional"}}},
