    ["03-37"] = {steps={[1]={desc="Du steigst in Dunkelhain und Seenhain um."}, [2]={npc="Demar Brant", tgt="Demar Brant"}, [3]={npc="Demar Brant", tgt="Demar Brant"}, [4]={npc="Demar Brant", tgt="Demar Brant", tag="Optional", desc="Du musst zuerst das durch Drop ausgelöste Logbuch des Feldmarschalls abgeben, sonst kannst du sie nicht annehmen."}, [5]={npc="Ashe Amberhall", tgt="Ashe Amberhall", tag="Optional"}, [6]={npc="Bertrand Ironbrow", tgt="Bertrand Ironbrow"}, [7]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [8]={hint="Sammelt 6 frische Äpfel für Tessa Dawnbright in Farholde.", tag="Im Spiel prüfen"}, [9]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [10]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [11]={hint="Sammelt 3 Koyotenpelze für Tessa Dawnbright in Farholde."}, [12]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [13]={npc="Tessa Dawnbright", tgt="Tessa Dawnbright"}, [14]={npc="Behüter Cornelius", tgt="Behüter Cornelius"}, [15]={text="Geh von Terrals Wacht nach Westen, südlich am Sonnengrund vorbei, zu Sergeant Riftan vor Twilight's Hood. Nimm im Vorbeigehen das Holz in Turners Holzfällerlager mit."}, [16]={hint="Sammelt 10 Holzbündel aus Turners Holzfällerlager für Bertrand Ironbrow in Farholde.", tag="Im Spiel prüfen"}, [17]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [18]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [19]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [20]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [21]={hint="Beschwört einen Twilight-Knecht aus einer Leitung im Twilight-Schleier und fangt ihn in Amberhalls Seelenstein ein.", tag="Optional", desc="Beschwöre am Leitgerät in Twilight's Hood einen Twilight-Knecht und fange ihn mit einem Seelenstein ein."}, [22]={npc="Marschall Ryan", tgt="Marschall Ryan", tag="Optional"}, [23]={npc="Marschall Ryan", tgt="Marschall Ryan", tag="Optional"}, [24]={hint="Rettet für Sergeant Riftan 5 Späher von Farholde im Twilight-Schleier.", tag="Im Spiel prüfen"}, [25]={hint="Besiegt 8 Twilight-Fanatiker, 8 Twilight-Verderber und 8 Twilight-Champions im Twilight-Schleier für Sergeant Riftan."}, [26]={hint="Besiegt für Sergeant Riftan 5 Ogerminenarbeiter und 5 Twilight-Unterwerfer im Twilight-Schleier."}, [27]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [28]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [29]={npc="Sergeant Riftan", tgt="Sergeant Riftan"}, [30]={npc="Sergeant Riftan", tgt="Sergeant Riftan", tag="Optional, Gruppe empfohlen", desc="Oberanführer Kilgar ist ein Elite der Stufe 46."}, [31]={hint="Besiegt Oberanführer Kilgar im Twilight-Schleier und bringt Sergeant Riftan seinen Kopf.", tag="Optional, Gruppe empfohlen", desc="Oberanführer Kilgar ist ein Elite der Stufe 46."}, [32]={npc="Sergeant Riftan", tgt="Sergeant Riftan", tag="Optional, Gruppe empfohlen", desc="Oberanführer Kilgar ist ein Elite der Stufe 46."}, [33]={npc="Sergeant Riftan", tgt="Sergeant Riftan", tag="Optional, Gruppe empfohlen", desc="Du musst zuerst Oberanführer Kilgar besiegen."}, [34]={text="Geh nach Osten durch den Sonnengrund und südlich an Terrals Wacht vorbei zum Hafen von Powderfuse und umgeh dabei Rog'mar, die Horde-Stadt. Der Hafen von Powderfuse hat keinen Flugpunkt der Allianz.", tag="Im Spiel prüfen"}, [35]={npc="Sleebo Fizzlespout", tgt="Sleebo Fizzlespout", tag="Optional", desc="Sleebo steht etwas nördlich der Straße zum Hafen von Powderfuse."}, [36]={hint="Sammelt 5 Marschengas-Phiolen für Sleebo Fizzlespout.", tag="Optional, Im Spiel prüfen"}, [37]={npc="Sleebo Fizzlespout", tgt="Sleebo Fizzlespout", tag="Optional"}, [38]={npc="Sleebo Fizzlespout", tgt="Sleebo Fizzlespout", tag="Optional"}, [39]={hint="Helft Sleebo, seine Erfindung zu testen.", tag="Optional, Im Spiel prüfen"}, [40]={npc="Sleebo Fizzlespout", tgt="Sleebo Fizzlespout", tag="Optional"}, [41]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [42]={npc="Gray Dawnbright", tgt="Gray Dawnbright"}, [43]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [44]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [45]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [46]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [47]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [48]={npc="GESUCHT!", npcObj=true, desc="Fallenklaue ist an der Küste östlich des Hafens von Powderfuse."}, [49]={hint="Tötet 8 Murlocorakel und 8 Murlockrieger an der Ostwindküste."}, [50]={hint="Sammelt 12 Murlocaugen und 6 Stück Sandkriecherfleisch für Fimbo Greasemitz."}, [51]={hint="Bringt Fallenklaues Zange zu Fimbo Greasemitz."}, [52]={hint="Tötet 10 Bukaniere der östlichen See und 10 Musketiere der östlichen See an der Ostwindküste, nördlich vom Hafen von Powderfuse."}, [53]={hint="Sammelt 8 Schmuggelwaren für Friz Frazzlespark im Hafen von Powderfuse.", desc="Erledige die Bukaniere und Musketiere der östlichen See zusammen mit Feindschaftlicher Wettbewerb."}, [54]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [55]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [56]={npc="Fimbo Greasemitz", tgt="Fimbo Greasemitz"}, [57]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [58]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [59]={npc="Friz Frazzlespark", tgt="Friz Frazzlespark"}, [60]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [61]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [62]={hint="Stehlt 5 Pulverfässchen der östlichen See für Werftmeister Whizzbuzz.", tag="Im Spiel prüfen", desc="Die Pulverfässchen stehen in den Gebäuden der Windbreak-Ruinen."}, [63]={hint="Tötet 8 Räuber der östlichen See und 8 Bombenschützen der östlichen See für Werftmeister Whizzbuzz."}, [64]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [65]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [66]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz"}, [67]={npc="Werftmeister Whizzbuzz", tgt="Werftmeister Whizzbuzz", tag="Optional"}, [68]={hint="Platziert ei