a"}, [53]={npc="Tabetha", tgt="Tabetha"}, [54]={hint="Tötet den Dämon der Kugel und sprecht dann mit Tabetha."}, [55]={npc="Tabetha", tgt="Tabetha"}, [56]={npc="Tabetha", tgt="Tabetha", desc="Im Dungeon Uldaman."}, [57]={hint="Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha.", desc="Im Dungeon Uldaman."}, [58]={npc="Tabetha", tgt="Tabetha", desc="Im Dungeon Uldaman."}, [59]={npc="Tabetha", tgt="Tabetha"}, [60]={hint="Vernichtet 12 Manawogen innerhalb des Zeitlimits."}, [61]={npc="Tabetha", tgt="Tabetha"}, [62]={npc="Tabetha", tgt="Tabetha"}, [63]={npc="Tabetha", tgt="Tabetha"}}},
