    ["04-45"] = {steps={[1]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew", tag="Optional", desc="Unterwegs erhältst du meist Feuerverzauberungen. Fällt keine, brich die Quest ab."}, [2]={npc="Garek", tgt="Garek", tag="Gruppe empfohlen, Optional", desc="Du musst zwei Elite-Schwarzdrachen der Stufe 50 töten; ohne Gruppe überspringst du das."}, [3]={hint="Benutzt das Zeichen der Erde, um die Amethyst-, Opal- und Diamantsäulen zu aktivieren und die Runensteine zu holen.", tag="Später unterwegs erledigen, Gruppe empfohlen, Optional"}, [4]={npc="Siegel der Erde", npcObj=true, tag="Gruppe empfohlen, Optional"}, [5]={npc="Siegel der Erde", npcObj=true, tag="Gruppe empfohlen, Optional"}, [6]={npc="Garek", tgt="Garek", tag="Gruppe empfohlen, Optional"}, [7]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew", tag="Optional"}, [8]={hint="Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Ironforge einen Beweis seines Tod."}, [9]={text="Geh aus dem Ödland nach Westen und nimm den Bergpfad neben Kargath, dem Lager der Horde, in die Sengende Schlucht. Umgehe Kargath.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [10]={npc="Hölzernes Plumpsklo", npcObj=true}, [11]={hint="Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff."}, [12]={text="Töte Margol den Wüterich, das bringt viel Erfahrung.", tag="Optional", desc="Das Horn von Margol beginnt die Questreihe um den Schlüssel zur Sengenden Schlucht; machst du sie nicht, überspring die Schritte 13, 32-33, 35, 37 und 40-42 und flieg in Schritt 43 von Eisenschmiede zurück zur Thoriumspitze."}, [13]={npc="Margols Horn", npcObj=true, tag="Optional", desc="Rechtsklicke Margols Horn im Rucksack, um die Quest anzunehmen."}, [14]={npc="Hölzernes Plumpsklo", npcObj=true}, [15]={npc="Hölzernes Plumpsklo", npcObj=true}, [16]={hint="Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht."}, [17]={npc="Dorius Stonetender", tgt="Dorius Stonetender"}, [18]={npc="Angesengter Brief", npcObj=true}, [19]={npc="Angesengter Brief", npcObj=true}, [20]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [21]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [22]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [23]={nodeA="{a:1446}"}, [24]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true, tag="Gruppe empfohlen, Optional", desc="Aufseher Maltorius ist ein Elite der Stufe 50; ohne Gruppe überspringst du das."}, [25]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true}, [26]={npc="Gesucht/Vermisst/Verloren & Gefunden", npcObj=true}, [27]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [28]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands", tag="Optional"}, [29]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [30]={npc="Meisterschmied Burninate", tgt="Meisterschmied Burninate"}, [31]={bindA="{a:144}"}, [32]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty", tag="Optional"}, [33]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty", tag="Optional"}, [35]={npc="Kurator Thorius", tgt="Kurator Thorius", tag="Optional"}, [36]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [37]={npc="Kurator Thorius", tgt="Kurator Thorius", tag="Optional"}, [38]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [39]={npc="Berater Belgrum", tgt="Berater Belgrum"}, [40]={tag="Optional", desc="Nur mit dem Beweis des Kurators (Endlich!) gehst du für den Schlüssel zurück zu Gebirgsjägerin Pebblebitty; sonst spring zu Schritt 43."}, [41]={npc="Gebirgsjägerin Pebblebitty", tgt="Gebirgsjägerin Pebblebitty", tag="Optional"}, [42]={text="Öffne mit dem frisch erhaltenen Schlüssel zur Sengenden Schlucht das Tor neben Gebirgsjägerin Pebblebitty und geh durch den Tunnel in die Sengende Schlucht.", tag="Optional"}, [43]={tag="Optional", desc="Hast du den Schlüssel zur Sengenden Schlucht nicht, flieg von Eisenschmiede direkt zurück zur Sengenden Schlucht. Bist du bereits durch den Tunnel hereingekommen, überspring das."}, [44]={hint="Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade."}, [45]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [46]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [47]={hint="Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht."}, [48]={hint="Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt."}, [49]={hint="Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet."}, [50]={hint="Hansel Heavyhands möchte, dass Ihr 20 sengende Lavaspinnen in der sengenden Schlucht tötet.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [51]={hint="Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet."}, [53]={hint="Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.", tag="Später unterwegs erledigen, Gruppe empfohlen, Optional"}, [54]={hint="Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht."}, [55]={hint="Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade."}, [56]={npc="Sterbender Archäologe", tgt="Sterbender Archäologe"}, [57]={npc="Sterbender Archäologe", tgt="Sterbender Archäologe", tag="Optional"}, [58]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [59]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [60]={hint="Sucht das mysteriöse Artefakt, das im Norden von den Twilight-Hammer bewacht wird.", tag="Später unterwegs erledigen"}, [61]={hint="Bringt ein Symbol von Ragnaros zu Velarok Windblade.", tag="Später unterwegs erledigen"}, [62]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle", tag="Optional"}, [63]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle", tag="Optional"}, [64]={npc="Zamael Lunthistle", tgt="Zamael Lunthistle", tag="Optional"}, [65]={npc="Ausguck Captain Lolo Longstriker", tgt="Ausguck Captain Lolo Longstriker", tag="Gruppe empfohlen, Optional"}, [66]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [67]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands", tag="Optional"}, [68]={npc="Hansel Heavyhands", tgt="Hansel Heavyhands"}, [69]={npc="Zuchtmeister Scrange", tgt="Zuchtmeister Scrange"}, [70]={npc="Zuchtmeister Scrange", tgt="Zuchtmeister Scrange"}, [71]={npc="Meisterschmied Burninate", tgt="Meisterschmied Burninate"}, [72]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Optional"}, [73]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [74]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [75]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [76]={npc="Fackel der Vergeltung", npcObj=true}, [77]={npc="Kalaran Windblade", tgt="Kalaran Windblade"}, [78]={npc="Knappe Maltrake", tgt="Knappe Maltrake"}, [79]={npc="Knappe Maltrake", tgt="Knappe Maltrake"}, [80]={hint="Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt."}, [81]={npc="Altar von Suntara", npcObj=true}, [82]={npc="Sterbender Archäologe", tgt="Sterbender Archäologe"}, [83]={hint="Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion."}, [84]={npc="Knappe Maltrake", tgt="Knappe Maltrake"}, [85]={npc="Hort des Schwarzdrachenschwarms", npcObj=true}, [86]={npc="Hort des Schwarzdrachenschwarms", npcObj=true}, [87]={text="Folge der Straße bis zu diesem Punkt."}, [88]={text="Spring in die Lava und stirb absichtlich: Eine Quest kann man nur als Geist annehmen."}, [89]={text="Lauf zu deiner Leiche zurück und belebe dich wieder."}, [90]={tag="Optional, Gruppe empfohlen", desc="Level hier nur mit einer Gruppe für die Schwarzfelstiefen bis 52. Solo überspringen."}, [91]={desc="Ist dein Ruhestein bereit, nutze ihn zurück nach Thelsamar und flieg von dort; sonst geh zurück zur Thoriumspitze (37.90, 30.40) und such den Flugmeister."}, [92]={npc="Kurator Thorius", tgt="Kurator Thorius"}, [93]={npc="Hochforscher Magellas", tgt="Hochforscher Magellas"}, [94]={npc="Historiker Karnik", tgt="Historiker Karnik"}, [95]={npc="Historiker Karnik", tgt="Historiker Karnik"}, [96]={text="Binde deinen Ruhestein im Gasthaus von Eisenschmiede (18.60, 51.60)."}, [97]={desc="Ist die Burg Nethergarde nicht freigeschaltet, flieg nach Dunkelhain, geh nach Osten durch den Gebirgspass der Totenwinde in die Sümpfe des Elends und dann nach Süden in die Verwüsteten Lande zur Burg Nethergarde."}, [98]={npc="Thadius Grimshade", tgt="Thadius Grimshade"}, [99]={npc="Cortellos Rätsel", npcObj=true, desc="Rechtsklicke Cortellos Rätsel im Rucksack, um die Quest anzunehmen. Erst ab Stufe 50 annehmbar."}, [100]={text="Geh von der Wache der Nethergarde nach Norden aus dem Verwüsteten Land in die Sümpfe des Elends und folge der Straße nach Westen bis zum Westteil des Sumpfs."}, [101]={npc="Eine glitschige Rolle", npcObj=true}, [102]={npc="Eine glitschige Rolle", npcObj=true}}},
    ["05-d11"] = {name="Blackrock Depths", nameA="{a:1584}", entrance="Sengende Schlucht 34.80, 85.30", steps={[1]={desc="In den Sümpfen des Elends gibt es keinen Flugpunkt der Allianz: Geh nach Westen durch den Gebirgspass der Totenwinde zurück nach Dunkelhain und flieg von dort."}, [2]={text="Geh von der Thoriumspitze nach Süden durch die Sengende Schlucht in den südlichen Schwarzfels."}, [3]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [4]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [5]={npc="Franclorn Forgewright", tgt="Franclorn Forgewright"}, [6]={text="Eingang: Blackrock Depths"}, [7]={hint="Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright."}, [8]={npc="Denkmal für Franclorn Forgewright", npcObj=true}, [9]={desc="Verlass den Schwarzfels nach Norden durch die Sengende Schlucht, kehr zur Thoriumspitze zurück und flieg von dort."}}},
    ["04-46"] = {steps={[1]={desc="In den Sümpfen des Elends gibt es keinen Flugpunkt der Allianz: Geh nach Westen durch den Gebirgspass der Totenwinde zurück nach Dunkelhain und flieg von dort."}, [2]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [3]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [4]={npc="Whiskey Slim", tgt="Whiskey Slim"}, [5]={npc="Seewolf MacKinley", tgt="Seewolf MacKinley"}, [6]={npc="Fin Fizracket", tgt="Fin Fizracket", tag="Optional"}, [7]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [8]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [9]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [10]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [11]={npc="Oglethorpe Obnoticus", tgt="Oglethorpe Obnoticus"}, [12]={tag="Optional"}, [13]={npc="Sorgfältig gefaltete Notiz", npcObj=true, desc="Rechtsklicke Sorgfältig gefaltete Notiz im Rucksack, um die Quest anzunehmen. Rechtsklicke jetzt die gefaltete Notiz von vorhin, um die Quest zu starten."}, [14]={npc="Prinzessin Poobah", tgt="Prinzessin Poobah"}, [15]={npc="Prinzessin Poobah", tgt="Prinzessin Poobah", tag="Optional"}, [16]={hint="Erschlagt König Mukla und kehrt mit dem Schlüssel zu Prinzessin Poobah zurück, um sie zu befreien.", tag="Später unterwegs erledigen"}, [17]={npc="Prinzessin Poobah", tgt="Prinzessin Poobah", tag="Optional"}, [19]={hint="Bringt Smotts' Truhe zu Hecklebury Smotts nach Booty Bay.", tag="Später unterwegs erledigen"}, [20]={hint="Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizracket.", tag="Später unterwegs erledigen"}, [21]={tag="Optional"}, [22]={npc="Fin Fizracket", tgt="Fin Fizracket", tag="Optional"}, [24]={hint="Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet."}, [26]={npc="Modrige Rolle", npcObj=true}, [27]={npc="Modrige Rolle", npcObj=true}}},
    ["04-47"] = {steps={[1]={desc="Die Schriftrolle liegt in der Raptorhöhle im Südwesten der Düstermarschen. Geh zuerst nach Osten zurück nach Theramore (67.48, 51.30) und flieg dann."}, [2]={npc="Krinkle Goodsteel", tgt="Krinkle Goodsteel"}, [3]={npc="Sprinkle", tgt="Sprinkle"}, [4]={npc="Sprinkle", tgt="Sprinkle"}, [5]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [6]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [7]={npc="Marin Noggenfogger", tgt="Marin Noggenfogger"}, [8]={text="Folge von Gadgetzan der Straße nach Norden zur Salzebene in Tausend Nadeln."}, [9]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [10]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [11]={npc="Gnomen-Boxenboss", tgt="Gnomen-Boxenboss"}, [12]={npc="Marvon Rivetseeker", tgt="Marvon Rivetseeker"}, [13]={npc="Uldum-Sockel", npcObj=true, tag="Optional"}, [14]={npc="Steinbehüter von Norgannon", tgt="Steinbehüter von Norgannon"}, [15]={npc="Uldum-Sockel", npcObj=true}, [16]={npc="Uldum-Sockel", npcObj=true, tag="Optional"}, [17]={text="Folge der Straße bis zu diesem Punkt."}}},
    ["04-48"] = {steps={[1]={text="Folge dem Bergpfad westlich von Tanaris die Rampe hinab in den Krater von Un'Goro. Torwa Pathfinder steht direkt am Eingang am Fuß der Rampe.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [2]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [3]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [4]={npc="Ein havariertes Floß", npcObj=true, desc="Sammle je 7 rote, blaue, grüne und gelbe Kristalle und hol dir „Ein zerfleddertes Tagebuch\" von den Raptoren."}, [5]={npc="Ein kleines Pack", npcObj=true}, [6]={npc="Ein kleines Pack", npcObj=true}, [7]={hint="Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück."}, [8]={desc="Töte Pflanzen bei etwa 67.7, 30.7, bis du Stufe 49 zur Hälfte hast."}, [9]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [10]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [11]={hint="Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen."}, [12]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [13]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [14]={hint="Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater.", tag="Optional", desc="Diese ist schwerer. Du kannst sie für die Rückkehr nach Un'Goro aufheben."}, [15]={npc="Karna Remtravel", tgt="Karna Remtravel"}, [16]={npc="Linken", tgt="Linken"}, [17]={npc="Linken", tgt="Linken"}, [18]={nodeA="{a:541}"}, [19]={npc="Williden Marshal", tgt="Williden Marshal"}, [20]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [21]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [22]={npc="J.D. Collie", tgt="J.D. Collie"}, [23]={npc="J.D. Collie", tgt="J.D. Collie"}, [24]={npc="J.D. Collie", tgt="J.D. Collie"}, [25]={npc="J.D. Collie", tgt="J.D. Collie"}, [26]={npc="J.D. Collie", tgt="J.D. Collie"}, [27]={npc="Vorsicht, Pterrordax!", npcObj=true}, [28]={npc="Muigin", tgt="Muigin"}, [29]={npc="Shizzle", tgt="Shizzle"}, [30]={hint="Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater."}, [31]={hint="Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze."}, [33]={hint="Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater."}, [34]={hint="Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater."}, [35]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [36]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [37]={text="Folge der Straße bis zu diesem Punkt."}, [38]={text="Folge der Straße bis zu diesem Punkt."}, [39]={hint="Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut."}, [40]={hint="Findet den Standort des westlichen Kristallpylonen."}, [41]={text="Schließ deine offenen Töte- und Sammelquests ab."}, [42]={hint="Sammelt 8 eingesponnene Dimetrodon-Schuppen und 8 eingesponnene Pterrordax-Schuppen für Shizzle in Marshals Zuflucht."}, [43]={hint="Sammelt 15 Blutblüten und kehrt zu Muigin zurück."}, [44]={hint="Tötet 10 Pterrordax und 15 rasende Pterrordax und sprecht dann mit Spraggle Frock in Marshals Zuflucht."}, [45]={npc="Shizzle", tgt="Shizzle"}, [46]={npc="Muigin", tgt="Muigin"}, [47]={npc="Muigin", tgt="Muigin"}, [48]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [49]={npc="Spark Nilminer", tgt="Spark Nilminer"}, [50]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [51]={npc="Williden Marshal", tgt="Williden Marshal"}, [52]={npc="Ein zerfleddertes Tagebuch", npcObj=true, tag="Optional", desc="Rechtsklicke Ein zerfleddertes Tagebuch nur, wenn du es von Gegnern erbeutet hast."}, [53]={npc="Williden Marshal", tgt="Williden Marshal", tag="Optional"}, [54]={npc="J.D. Collie", tgt="J.D. Collie"}, [55]={npc="J.D. Collie", tgt="J.D. Collie"}, [56]={npc="J.D. Collie", tgt="J.D. Collie"}, [57]={npc="J.D. Collie", tgt="J.D. Collie"}, [58]={npc="J.D. Collie", tgt="J.D. Collie"}, [60]={desc="Hat dein Ruhestein Abklingzeit, flieg von Marshals Zuflucht nach Auberdine (über Gadgetzan und Theramore) und überspring die nächsten zwei Schritte."}, [62]={desc="Dieses Schiff hält unterwegs in Süderstade. Steig erst in Auberdine aus."}, [64]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [65]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [66]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [67]={text="Geh in Rut'theran durch das Portal nach Darnassus."}, [68]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [69]={npc="Gracina Spiritmight", tgt="Gracina Spiritmight"}, [70]={npc="Astarii Starseeker", tgt="Astarii Starseeker", tag="Optional"}, [71]={text="Geh in Darnassus durch das Portal zurück nach Rut'theran."}, [73]={text="Binde deinen Ruhestein im Gasthaus von Astranaar (37.00, 49.20).", bindA="{a:415}"}, [74]={npc="Maginor Dumas", tgt="Maginor Dumas", tag="Optional", desc="Die Einführung in Sturmwind kannst du überspringen. In Azshara musst du dich trotzdem zuerst von Sanath Lim-yo auf die Klippe teleportieren lassen."}, [75]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Optional", desc="Gib sie hier nur ab, wenn du die Einführung angenommen hast."}, [76]={text="Sprich mit Sanath Lim-yo und bitte ihn, dich auf die Klippe zu Erzmagier Xylem zu teleportieren."}, [77]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem"}, [78]={hint="Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben."}, [79]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", desc="Der Staub liegt unten am Berg; lass dich genauso von Sanath Lim-yo wieder hinaufteleportieren."}, [80]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem"}, [81]={hint="Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem."}, [82]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem"}, [83]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [84]={hint="Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [85]={npc="Erzmagier Xylem", tgt="Erzmagier Xylem", desc="Morphaz ist im Tempel von Atal'Hakkar. Zum Abstieg von der Klippe benutze deinen Ruhestein oder such die Teleportoption neben Xylem (im Spiel prüfen)."}, [86]={npc="Bruder Joshua", tgt="Bruder Joshua", desc="Nimm sie in Sturmwind an und gib sie bei Ogtinc in Azshara ab."}, [87]={npc="Ogtinc", tgt="Ogtinc", desc="Nimm sie in Sturmwind an und gib sie bei Ogtinc in Azshara ab."}, [88]={npc="Ogtinc", tgt="Ogtinc"}, [89]={hint="Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath."}, [90]={npc="Ogtinc", tgt="Ogtinc"}, [91]={npc="Ogtinc", tgt="Ogtinc"}, [92]={hint="Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath."}, [93]={npc="Ogtinc", tgt="Ogtinc"}, [94]={npc="Ogtinc", tgt="Ogtinc", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [95]={hint="Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends.", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [96]={npc="Greta Mosshoof", tgt="Greta Mosshoof", desc="Morphaz ist im Tempel von Atal'Hakkar."}, [97]={npc="Dorion", tgt="Dorion", desc="Nimm sie in Darnassus (oder Eisenschmiede, Sturmwind) an und gib sie bei Ogtinc in Azshara ab."}, [98]={npc="Ogtinc", tgt="Ogtinc", desc="Nimm sie in Darnassus (oder Eisenschmiede, Sturmwind) an und gib sie bei Ogtinc in Azshara ab."}, [99]={npc="Ogtinc", tgt="Ogtinc"}, [100]={hint="Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath."}, [101]={npc="Ogtinc", tgt="Ogtinc"}, [102]={npc="Ogtinc", tgt="Ogtinc"}, [103]={hint="Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath."}, [104]={npc="Ogtinc", tgt="Ogtinc"}, [105]={npc="Ogtinc", tgt="Ogtinc", desc="Der grüne Drache ist im Tempel von Atal'Hakkar."}, [106]={hint="Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.", desc="Der grüne Drache ist im Tempel von Atal'Hakkar."}, [107]={npc="Ogtinc", tgt="Ogtinc", desc="Der grüne Drache ist im Tempel von Atal'Hakkar."}}},
    ["04-49"] = {steps={[1]={text="Folge von Astranaar der Straße nach Norden in den Teufelswald.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [2]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [3]={npc="Grazle", tgt="Grazle"}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [6]={npc="Taronn Redfeather", tgt="Taronn Redfeather", tag="Optional"}, [7]={hint="Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt."}, [8]={npc="Grazle", tgt="Grazle"}, [9]={npc="Grazle", tgt="Grazle"}, [10]={hint="Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist."}, [11]={hint="Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}, [12]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [13]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [14]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [15]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [16]={hint="Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt."}, [17]={desc="Töte Gegner bei 35, 59 in Jaedenar."}, [18]={hint="Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [19]={hint="Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt."}, [20]={npc="Flöte des Xavaric", npcObj=true, desc="Rechtsklicke Flöte des Xavaric im Rucksack, um die Quest anzunehmen."}, [21]={hint="Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Bluewind im südlichen Teil des Teufelswalds."}, [22]={hint="Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald."}, [23]={nodeA="{a:1998}"}, [24]={npc="Nafien", tgt="Nafien"}, [25]={npc="Nafien", tgt="Nafien", tag="Im Spiel prüfen"}, [26]={hint="Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.", tag="Im Spiel prüfen"}, [27]={npc="Nafien", tgt="Nafien", tag="Im Spiel prüfen"}, [28]={text="Folge der Straße bis zu diesem Punkt.", desc="Betritt hier die Höhle der Holzschlundfeste und geh hindurch, dahinter liegt Winterquell."}, [29]={node="Moonglade", tag="Im Spiel prüfen", desc="In der Höhle der Holzschlundfeste führt eine Abzweigung nach Moonglade; geh zuerst hinüber, schalte den Flugpunkt frei und kehr dann in die Höhle zurück, um nach Winterquell zu gehen. Für den Abschnitt im Hyjal später fliegst du nach Moonglade."}, [30]={npc="Salfa", tgt="Salfa", tag="Im Spiel prüfen"}, [31]={npc="Donova Snowden", tgt="Donova Snowden"}, [32]={npc="Donova Snowden", tgt="Donova Snowden"}, [33]={npc="Meggi Peppinrocker", tgt="Meggi Peppinrocker"}, [34]={npc="Jessica Redpath", tgt="Jessica Redpath"}, [35]={nodeA="{a:2255}"}, [36]={npc="Niby der Allmächtige", tgt="Niby der Allmächtige"}, [37]={npc="Impsy", tgt="Impsy"}, [38]={npc="Impsy", tgt="Impsy"}, [39]={hint="Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."}, [40]={npc="Impsy", tgt="Impsy"}, [41]={npc="Impsy", tgt="Impsy"}, [42]={hint="Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald."}, [43]={npc="Impsy", tgt="Impsy"}, [44]={npc="Impsy", tgt="Impsy"}, [45]={hint="Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel."}, [46]={npc="Impsy", tgt="Impsy"}, [47]={npc="Impsy", tgt="Impsy"}, [48]={hint="Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt."}, [49]={npc="Impsy", tgt="Impsy"}, [50]={npc="Impsy", tgt="Impsy", desc="Kroshius ist im Norden des Teufelswalds. Du brauchst eine Gruppe."}, [51]={hint="Sucht im Shattered Scar-Tal im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.", desc="Kroshius ist im Norden des Teufelswalds. Du brauchst eine Gruppe."}, [52]={npc="Niby der Allmächtige", tgt="Niby der Allmächtige", desc="Kroshius ist im Norden des Teufelswalds. Du brauchst eine Gruppe."}}},
    ["04-50"] = {steps={[2]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [3]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [4]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}, [5]={npc="Gregan Brewspewer", tgt="Gregan Brewspewer"}, [6]={npc="Felsbeißer", tgt="Felsbeißer"}, [7]={hint="Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück."}, [8]={hint="Aktiviert Troyas Stock und findet den Equinex-Monolithen.", desc="Weiter hinten kannst du hochspringen und abkürzen."}, [9]={npc="Shay Leafrunner", tgt="Shay Leafrunner"}, [10]={npc="Equinex-Monolith", npcObj=true, desc="Benutze den Stab in deinem Rucksack."}, [11]={npc="Equinex-Monolith", npcObj=true}, [12]={hint="Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge."}, [13]={npc="Makelloser Yetibalg", npcObj=true, tag="Optional", desc="Droppt beim Töten der Yetis ein Makelloser Yetibalg, rechtsklicke ihn."}, [14]={npc="Pratt McGrubben", tgt="Pratt McGrubben"}, [15]={npc="Pratt McGrubben", tgt="Pratt McGrubben", tag="Optional"}, [16]={npc="Troyas Moonbreeze", tgt="Troyas Moonbreeze"}}},
    ["04-51"] = {steps={[1]={bindA="{a:415}", desc="Hat dein Ruhestein Abklingzeit, flieg von der Mondfederfeste nach Astranaar (über Auberdine) und geh dann nach Norden in den Teufelswald."}, [2]={npc="Arathandris Silversky", tgt="Arathandris Silversky"}, [3]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [4]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [5]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [6]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [7]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [8]={npc="Taronn Redfeather", tgt="Taronn Redfeather"}, [9]={npc="Donova Snowden", tgt="Donova Snowden", desc="Flieg zurück nach Astranaar und dann zur Krallenzweiglichtung, geh dann nach Norden durch die Holzschlundfeste nach Winterquell."}, [10]={npc="Donova Snowden", tgt="Donova Snowden"}, [11]={npc="Donova Snowden", tgt="Donova Snowden"}, [12]={npc="Donova Snowden", tgt="Donova Snowden"}, [13]={desc="Töte Furbolgs bei 32, 36 im Lager der Winterfelle."}, [14]={npc="Gregor Greystone", tgt="Gregor Greystone"}, [15]={npc="Gregor Greystone", tgt="Gregor Greystone"}, [16]={desc="Du steigst an der Talrendisspitze um."}, [17]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [18]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [19]={npc="Islen Waterseer", tgt="Islen Waterseer"}, [21]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg"}, [22]={text="Bleib nach dem Trinken des Videre-Elixiers tot und such den Quest-NPC als Geist."}, [23]={npc="Gaeriyan", tgt="Gaeriyan"}, [24]={npc="Gaeriyan", tgt="Gaeriyan"}, [25]={text="Kehr zu deiner Leiche zurück und belebe dich wieder."}, [26]={npc="Ein verdächtiger Grabstein", npcObj=true}, [27]={npc="Ein verdächtiger Grabstein", npcObj=true}, [28]={npc="Tran'rek", tgt="Tran'rek"}, [29]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg"}}},
    ["04-52"] = {steps={[2]={npc="Linken", tgt="Linken"}, [3]={npc="Linken", tgt="Linken"}, [4]={npc="J.D. Collie", tgt="J.D. Collie"}, [5]={npc="J.D. Collie", tgt="J.D. Collie"}, [6]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [7]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal", tag="Optional"}, [8]={hint="Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan."}, [9]={npc="Krakle", tgt="Krakle"}, [10]={hint="Sammelt 9 Proben Un'Goro-Asche von den Feuerelementare am Vulkan im Un'Goro Krater ein und bringt die Proben zu Liv Rizzlefix in Ratchet."}, [11]={hint="Krakle im Un'Goro Krater möchte, dass Ihr den heißesten Bereich des Feuerfedergrats findet."}, [12]={hint="Bringt eine Gorishiduftdrüse und 5 Un'Goro-Erdproben zu Alchimist Pestlezugg in Gadgetzan.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [13]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [14]={npc="Krakle", tgt="Krakle"}, [15]={npc="Krakle", tgt="Krakle"}, [16]={npc="Ringo", tgt="Ringo", desc="Eskortquest: In der Gruppe erst annehmen, wenn alle gleich weit sind, und automatisches Annehmen ausschalten."}, [17]={npc="Ringo", tgt="Ringo"}, [18]={hint="Führt Ringo zu Spraggle Frock in Marshals Zuflucht.", tag="Eskorte", desc="Bring Ringo zurück zu Marshals Zuflucht. Er wird unterwegs ohnmächtig; benutze dann Spraggles Feldflasche an ihm."}, [19]={npc="Spraggle Frock", tgt="Spraggle Frock"}, [20]={npc="A-Me 01", tgt="A-Me 01"}, [21]={npc="A-Me 01", tgt="A-Me 01"}, [22]={hint="Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Un'Goro Krater.", desc="Kauf das Mithrilgehäuse vorher im Auktionshaus oder lass es einen Ingenieur herstellen."}, [23]={npc="A-Me 01", tgt="A-Me 01"}, [24]={hint="Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters."}, [25]={npc="A-Me 01", tgt="A-Me 01"}, [26]={hint="Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater.", tag="Eskorte", desc="Eskortiere A-Me 01 zurück zu Karna Remtravel; Gegner am Weg greifen ihn an, also beschütze ihn."}, [27]={npc="Karna Remtravel", tgt="Karna Remtravel"}, [28]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [29]={text="Bei Torwa gibt es keinen Flugpunkt: Verlass den Krater von Un'Goro über die Rampe hinter ihm nach Tanaris und lauf nach Nordosten nach Gadgetzan."}, [30]={npc="Tran'rek", tgt="Tran'rek"}, [31]={npc="Alchimist Pestlezugg", tgt="Alchimist Pestlezugg", tag="Optional"}, [32]={desc="Du steigst in Theramore um."}, [33]={npc="Liv Rizzlefix", tgt="Liv Rizzlefix"}, [34]={bindA="{a:415}"}, [36]={text="Binde deinen Ruhestein im Gasthaus von Auberdine bei Gastwirtin Shaussiy (37.04, 44.13)."}, [38]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [39]={text="Geh in Rut'theran durch das Portal nach Darnassus."}, [40]={hint="Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück."}, [41]={text="Geh in Darnassus durch das Portal zurück nach Rut'theran."}, [43]={npc="Greta Mosshoof", tgt="Greta Mosshoof"}, [44]={npc="Greta Mosshoof", tgt="Greta Mosshoof", tag="Optional"}, [45]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [46]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [47]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [48]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [49]={npc="Eridan Bluewind", tgt="Eridan Bluewind"}, [50]={hint="Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [51]={npc="Eridan Bluewind", tgt="Eridan Bluewind", tag="Optional"}, [52]={desc="Hat er Abklingzeit, lauf zurück nach Astranaar und flieg nach Auberdine."}, [53]={desc="Dieses Schiff hält unterwegs in Süderstade. Steig erst in Menethil aus."}, [55]={npc="Historiker Karnik", tgt="Historiker Karnik", tag="Optional"}, [56]={npc="Historiker Karnik", tgt="Historiker Karnik", tag="Optional"}, [57]={npc="Hochforscher Magellas", tgt="Hochforscher Magellas", tag="Optional"}, [58]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus"}, [59]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus"}, [60]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus"}, [61]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [62]={hint="Sammelt Blutkappenpilze und Gorishistachel und kehrt zu Torwa Pathfinder im Un'Goro Krater zurück."}, [63]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [64]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [65]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [66]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}, [67]={hint="Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des versunkenen Tempels und kehrt zu Torwa Pathfinder zurück."}, [68]={npc="Torwa Pathfinder", tgt="Torwa Pathfinder"}}},
    ["04-54"] = {steps={[1]={text="Hast du Morgans Wacht freigeschaltet, flieg direkt von Eisenschmiede dorthin. Sonst flieg nach Seenhain und folge der Straße nach Norden in die Brennende Steppe; Morgans Wacht liegt gleich am Eingang.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [2]={nodeA="{a:2418}"}, [3]={npc="Oralius", tgt="Oralius"}, [4]={npc="Oralius", tgt="Oralius"}, [5]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Optional"}, [6]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [7]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [8]={hint="Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt."}, [9]={hint="Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel."}, [10]={hint="Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid."}, [11]={hint="Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe."}, [12]={hint="Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.", tag="Später unterwegs erledigen"}, [13]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Optional"}, [14]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Optional"}, [15]={npc="Tinkee Steamboil", tgt="Tinkee Steamboil"}, [16]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [17]={npc="Oralius", tgt="Oralius"}, [18]={npc="Oralius", tgt="Oralius", tag="Optional"}, [19]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Optional"}, [20]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Optional"}, [21]={hint="Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück.", tag="Optional"}, [22]={hint="Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet."}, [23]={npc="Oralius", tgt="Oralius"}, [24]={npc="Oralius", tgt="Oralius", tag="Optional"}, [25]={desc="Überspringst du Die wahren Meister, flieg direkt nach Sturmwind und überspring die nächsten zwei Schritte."}, [26]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Optional"}, [27]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Optional"}, [29]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Optional"}, [30]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Optional"}, [31]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Optional"}, [32]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Optional"}, [33]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Optional"}, [34]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", tag="Optional"}, [35]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", tag="Optional"}, [36]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", tag="Optional"}, [37]={npc="Meister Mathias Shaw", tgt="Meister Mathias Shaw", tag="Optional"}, [38]={npc="Ausrufer Goodman", tgt="Ausrufer Goodman"}, [39]={npc="Wu Shen", tgt="Wu Shen", tag="Optional"}, [40]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [41]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [42]={hint="Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück.", tag="Optional"}, [43]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [44]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [45]={hint="Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück.", tag="Optional"}, [46]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [47]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [48]={hint="Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde.", tag="Optional"}, [49]={npc="Gefallener Held der Horde", tgt="Gefallener Held der Horde", tag="Optional"}, [50]={npc="Lord Grayson Shadowbreaker", tgt="Lord Grayson Shadowbreaker", desc="Gib sie auf der Chillwindspitze in den Westlichen Pestländern ab."}}},
    ["04-55"] = {steps={[1]={desc="Hast du die Chillwindspitze freigeschaltet, flieg direkt dorthin und überspring den nächsten Schritt. Ist der Nistgipfel nicht auf deiner Flugkarte, flieg nach Süderstade und lauf auf demselben Weg wie bei der Hinterland-Etappe nach Osten zum Nistgipfel."}, [2]={text="Geh vom Nistgipfel auf dem Bergpfad nach Norden in die Südostecke der Westlichen Pestländer (65.30, 86.80) und folge dann der Straße nach Westen zur Chillwindspitze.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß."}, [3]={nodeA="{a:3197}"}, [4]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [5]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [6]={npc="Argentumoffizier Pureheart", tgt="Argentumoffizier Pureheart"}, [7]={npc="Argentumoffizier Pureheart", tgt="Argentumoffizier Pureheart"}, [8]={npc="Argentumoffizier Pureheart", tgt="Argentumoffizier Pureheart"}, [9]={npc="Argentumoffizier Pureheart", tgt="Argentumoffizier Pureheart", desc="Eine Briefliefer-Quest; gib sie in der Nähe des Eingangs zum Hyjal ab."}, [10]={npc="Flint Shadowmore", tgt="Flint Shadowmore"}, [11]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [12]={hint="Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill."}, [13]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [14]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [15]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [16]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [17]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [18]={hint="Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren."}, [19]={hint="Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}, [20]={npc="Geißelkessel", npcObj=true}, [21]={npc="Geißelkessel", npcObj=true}, [22]={npc="Janice Teufelsstein", tgt="Janice Teufelsstein"}, [23]={npc="Janices Paket", npcObj=true}, [24]={npc="Janices Paket", npcObj=true}, [25]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [26]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [27]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [28]={hint="Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}, [29]={npc="Geißelkessel", npcObj=true}, [30]={npc="Geißelkessel", npcObj=true}, [31]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [32]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [33]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [34]={hint="Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}, [35]={npc="Geißelkessel", npcObj=true}, [36]={npc="Geißelkessel", npcObj=true}, [37]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [38]={hint="Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück."}, [39]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [40]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [41]={hint="Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück."}, [42]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [43]={npc="Mulgris Deepriver", tgt="Mulgris Deepriver"}, [44]={text="Folge der Straße bis zu diesem Punkt."}, [45]={text="Binde deinen Ruhestein im Gasthaus von Aerie Peak (13.80, 41.60).", bindA="{a:348}"}, [46]={npc="Cortellos Schatz", npcObj=true}, [47]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [48]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [49]={hint="Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern."}, [50]={npc="Hohepriester Thel'danis", tgt="Hohepriester Thel'danis"}, [51]={npc="Hohepriester Thel'danis", tgt="Hohepriester Thel'danis"}, [52]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [53]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", desc="Gib sie ab, um den Machtstein zu erhalten."}, [54]={hint="Bringt die Voodoofedern zu Ashlam Valorfist.", desc="Gib sie ab, um den Machtstein zu erhalten."}, [55]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist", desc="Gib sie ab, um den Machtstein zu erhalten."}, [56]={bindA="{a:348}"}}},
    ["04-56"] = {steps={[1]={text="Geh vom Nistgipfel auf dem Bergpfad nach Norden in die Westlichen Pestländer, dann nach Osten über den Thondroril in die Östlichen Pestländer. Tirion Fordring ist in der Hütte direkt am Eingang."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [5]={hint="Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt."}, [6]={hint="Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück."}, [7]={hint="Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt."}, [8]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [9]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [10]={hint="Sucht Pamelas Puppe.", desc="Sammle in den zerstörten Häusern von Darrowshire Kopf, linke und rechte Seite und kombiniere sie per Rechtsklick."}, [11]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [12]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [13]={npc="Pamela Redpath", tgt="Pamela Redpath"}, [14]={npc="Fürst Nicholas Zverenhoff", tgt="Fürst Nicholas Zverenhoff"}, [15]={node="Kapelle des hoffnungsvollen Lichts"}, [16]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [17]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [18]={npc="Verwalter Alen", tgt="Verwalter Alen"}, [19]={hint="Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [21]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [22]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [23]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [24]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [25]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [26]={hint="Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."}, [27]={hint="Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts."}, [28]={npc="Zerrissene Rolle", npcObj=true}, [29]={hint="Sucht in den östlichen Pestländern nach Hinweisen auf den 'Blightcaller' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Shadowmore an der Chillwindspitze.", tag="Optional"}, [30]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [31]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [32]={npc="Verwalter Alen", tgt="Verwalter Alen"}, [33]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}}},
    ["04-53"] = {steps={[1]={desc="Du steigst an der Chillwindspitze oder am Nistgipfel um; ist Süderstade nicht auf deiner Flugkarte, flieg wie gewohnt nach Sturmwind und nimm im Hafen das Schiff nach Auberdine."}, [2]={desc="Am Pier von Süderstade legt direkt ein Schiff nach Auberdine ab; das geht schneller, als nach Sturmwind zu fliegen und umzusteigen. Fliegst du stattdessen nach Sturmwind, geh im Hafen von Sturmwind an Bord."}, [4]={hint="Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt."}, [5]={hint="Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich direkt außerhalb des Eingangs zur Holzschlundfeste in Winterspring.", tag="Im Spiel prüfen"}, [6]={npc="Leeres Feuerwasserfläschchen", npcObj=true, desc="Rechtsklicke Leeres Feuerwasserfläschchen im Rucksack, um die Quest anzunehmen."}, [7]={npc="Donova Snowden", tgt="Donova Snowden"}, [8]={npc="Donova Snowden", tgt="Donova Snowden"}, [9]={npc="Donova Snowden", tgt="Donova Snowden"}, [10]={npc="Donova Snowden", tgt="Donova Snowden"}, [11]={npc="Donova Snowden", tgt="Donova Snowden", desc="Das Erkunden der Flüsternde Schlucht erledigst du an der nächsten Station auf dem Weg in den Hyjal; gib es ab, bevor du zurück nach Winterquell und weiter nach Moonglade gehst. Gib es ab, bevor du zurück nach Winterquell und weiter nach Moonglade gehst."}, [12]={hint="Sammelt 10 mondbestrahlte Federn aus Winterspring und kehrt dann zu Erelas Ambersky in Rut'theran zurück."}, [13]={npc="Salfa", tgt="Salfa", tag="Im Spiel prüfen"}, [14]={npc="Kessel der Totenwaldfelle", npcObj=true}, [15]={npc="Kessel der Totenwaldfelle", npcObj=true}, [16]={desc="Geh vom Kessel der Totenwaldfelle nach Süden zum Flugpunkt Krallenzweiglichtung (62.49, 24.24) und flieg von dort ab; du steigst in Auberdine um."}, [17]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [18]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [19]={npc="Daryn Lightwind", tgt="Daryn Lightwind"}, [21]={npc="Harlo Wigglesworth", tgt="Harlo Wigglesworth"}, [22]={npc="Wynd Nightchaser", tgt="Wynd Nightchaser"}, [23]={npc="Wynd Nightchaser", tgt="Wynd Nightchaser"}, [24]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [25]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [26]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [27]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper"}, [28]={hint="Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern."}, [29]={npc="Donova Snowden", tgt="Donova Snowden"}, [30]={npc="Beschädigte Kiste", npcObj=true}, [31]={npc="Beschädigte Kiste", npcObj=true}, [32]={npc="Jarons Wagen", npcObj=true}, [33]={npc="Jarons Wagen", npcObj=true}, [34]={hint="Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte."}, [35]={npc="Ranshalla", tgt="Ranshalla"}, [36]={npc="Ranshalla", tgt="Ranshalla"}, [37]={hint="Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Ambersky in Rut'theran von Eurem Fund."}}},
    ["04-57"] = {danger={[1]="Ghansurok (Elite-Schimäre der Stufe 61) patrouilliert von den befleckten Hibiskussträuchern bis zu Kaylaenas Werkstatt (etwa x55-62,5, y61,5-72,2); prüfe seine Position beim Bearbeiten der Büsche und auf dem Rückweg zur Werkstatt.", [2]="Celastrus der Bittere (Elite der Stufe 57) streift um die befleckten Hibiskussträucher; achte beim Bearbeiten der Büsche auf ihn.", [3]="Der Knochenhaufen ruft einen Elite-Schleim der Stufe 58 herbei; ohne Gruppe klick ihn kein zweites Mal an."}, grind={[1]={note="Der Nordteil der Teuflischen Blutnarbe; alle Quests von Felflick kämpfst du hier."}}, supply={[1]={}}, steps={[1]={text="Geh von Ranshalla nach Süden in die Flüsternde Schlucht, folge der Schlucht nach Westen bis zum Ende und betritt so den Hyjal. Am Eingang steht ein Elite-Frostriese, in der Schlucht gibt es Elite-Dämonen; bleib auf der Straße und halte nicht an.", tag="Flugpunkt noch nicht freigeschaltet. Geh beim ersten Besuch zu Fuß., Im Spiel prüfen"}, [2]={hint="Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr.", tag="Im Spiel prüfen", desc="Es wird beim Weg durch die Schlucht in den Hyjal abgeschlossen; ein Umweg ist nicht nötig. Sie zählt, sobald das Questlog sie als abgeschlossen anzeigt."}, [3]={text="Betritt den Hyjal an der Südostecke und folge der Straße nach Westen.", tag="Im Spiel prüfen"}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Lockeres Zahnrad", npcObj=true, desc="Ein Zahnrad am Boden neben der Straße; klick es mit rechts an, um es aufzuheben und die Quest anzunehmen."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Optional"}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rettet 12 Hyjaleuleneier und bringt sie zu Ketharas."}, [14]={hint="Sammelt 10 unbefleckte Samen für Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Sammelt 2 Stücke Wildfleisch von unbefleckten Hyjalhirschen und 6 scharlachrote Wurmknollen für den Eintopf des Einsiedlers."}, [20]={hint="Pflanzt die verzauberten Samen in der Nähe der zerstörten Balliste, des zerstörten Katapults und der zerstörten Flugmaschine.", tag="Im Spiel prüfen", desc="Die Wracks von Balliste, Katapult und Fluggerät zählen jeweils als ein Ziel; du musst alle drei bepflanzen."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Vergrabt die Überreste an Ketharas' Schrein.", tag="Im Spiel prüfen", desc="Die Koordinaten sind die von Spielern gemeldete ungefähre Position."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={nodeA="{a:16853}", desc="Folge der Straße nach Westen; der Flugpunkt liegt neben dem Außenposten der Uralten."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Gruppe empfohlen, Optional", desc="Das Ziel ist ein Elite der Stufe 57; schaffst du es solo nicht, nimm sie nicht an."}, [32]={hint="Sammelt 6 Proben unbefleckter Erde in den Ausläufern des Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Wenn du später nach Everlook gehst, hol dir die Teile bei Nami."}, [36]={hint="Zerstört 15 besudelte Gebüsche für Kaylaena Springwhisper bei der Werkstatt im Besudelten Vorgebirge.", desc="Dieselben Hibiskussträucher lassen auch die blutstillenden Blätter fallen; bekämpfe sie für beide Quests zusammen. Gib es in der Werkstatt ab, wenn du die Kiste lieferst."}, [37]={hint="Sammelt 12 tiefgrüne Blätter von besudelten Gebüschen in den Ausläufern des Hyjal."}, [38]={hint="Findet und vernichtet Celastrus den Bitteren und kehrt dann mit dem zerbrochenen Wedel zu Thylaen zurück.", tag="Gruppe empfohlen, Optional"}, [39]={npc="Hyacinth", tgt="Hyacinth"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Thylaen", tgt="Thylaen", tag="Gruppe empfohlen, Optional"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Wendet den Umschlag bei Fraxinus an."}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Gruppe empfohlen, Optional", desc="Das Ziel, Rindenriss, ist ein Elite-Uralter der Stufe 56; mach es mit einer Gruppe. Ohne Gruppe überspring die Schritte \"Die sterbenden Urtume\", \"Die sterbenden Urtume\", \"Die sterbenden Urtume\"."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [48]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [49]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Tötet 12 Aschenakolythen.", desc="Die Notizen fallen von denselben Akolythen; kämpfe also für beide Quests gegen sie."}, [53]={hint="Findet 12 Hinweise zum Experimentieren mit Teufelsasche."}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Sammelt 8 Teufelsschleimkristalle und 1 makellosen Teufelsschleimkristall."}, [57]={npc="Felflick", tgt="Felflick"}, [58]={npc="Felflick", tgt="Felflick"}, [59]={npc="Felflick", tgt="Felflick"}, [60]={hint="Bergt die Knochen von Frezzlie Popwhiz, Tyaeha Darkoath und Dazka Shadowsleep."}, [61]={hint="Tötet Brashann Grimdark und sucht seine Leiche nach seinem Seelenstein ab."}, [62]={npc="Felflick", tgt="Felflick"}, [63]={npc="Felflick", tgt="Felflick"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Knochenhaufen", npcObj=true, desc="Wirf die Hexenmeisterknochen auf den Knochenhaufen neben dem Schleimbecken."}, [66]={npc="Knochenhaufen", npcObj=true, tag="Gruppe empfohlen, Optional", desc="Es ruft einen Elite-Schleim der Stufe 58 herbei. Ohne Gruppe überspring die Schritte \"Verschmolzenes Mark\"-\"Verschmolzenes Mark\", \"Verschmolzenes Mark\"-\"Bittere Rache\", \"Bittere Rache\"."}, [67]={hint="Tötet den erweckten Teufelsascheschleim.", tag="Gruppe empfohlen, Optional"}, [68]={npc="Velician", tgt="Velician"}, [69]={npc="Felflick", tgt="Felflick", tag="Gruppe empfohlen, Optional"}, [70]={npc="Felflick", tgt="Felflick", tag="Gruppe empfohlen, Optional"}, [71]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [72]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [73]={npc="Seltsame Krähe", tgt="Seltsame Krähe", tag="Gruppe empfohlen, Optional"}, [74]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [75]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [76]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [77]={hint="Sammelt 8 Teufelsschleimschlamm."}, [78]={hint="Sammelt 10 stachelige Kiefernzapfen unter gesunden Bäumen."}, [79]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [80]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [81]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [82]={hint="Verwendet die Kiefernzapfen, um die Arbeitsstationen des Kults der Ascheherrschaft zu zerstören.", tag="Im Spiel prüfen"}, [83]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [84]={npc="Seltsame Krähe", tgt="Seltsame Krähe", desc="Gib es an der nächsten Station im westlichen Elderwild ab."}, [85]={hint="Spürt das verderbte Urtum Rindenriss auf, vernichtet es und pflanzt dann einen Samen in seinen Überresten.", tag="Gruppe empfohlen, Optional", desc="Auf dem Rückweg nach Osten zur Einsiedlerhöhle."}, [86]={npc="Ketharas", tgt="Ketharas"}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={npc="Fraxinus", tgt="Fraxinus", tag="Gruppe empfohlen, Optional"}, [90]={npc="Nami", tgt="Nami", desc="Die Folgekiste hat ein Zeitlimit; nimm sie erst an, wenn du aus Moonglade zurück bist."}, [91]={npc="Jaron Stoneshaper", tgt="Jaron Stoneshaper", desc="Folge von Everlook der Straße ein kurzes Stück nach Westen bis Starfall Village."}, [92]={text="Reite von Starfall Village auf der Straße nach Südwesten zur heißen Quelle und such Donova.", tag="Im Spiel prüfen"}, [93]={npc="Donova Snowden", tgt="Donova Snowden"}, [94]={desc="Reite von der heißen Quelle zurück zum Flugpunkt in Everlook und flieg (den Flugpunkt in Moonglade hast du an Station 49 freigeschaltet). Ist dein Ruf bei den Holzschlundbären schon neutral, reite von der heißen Quelle nach Norden zum Eingang der Holzschlundfeste (27.70, 34.50); durch die Höhle zum Ausgang nach Moonglade ist es näher; auch wer den Flugpunkt in Moonglade noch nicht hat, nimmt diesen Weg und schaltet bei der Ankunft zuerst den Flugpunkt frei (48.10, 67.34); unter neutral wirst du angegriffen. Druiden können direkt Teleportieren: Moonglade nutzen; nach der Ankunft gehst du zum normalen Flugpunkt (48.10, 67.34) und schaltest ihn frei, damit du zurückfliegen kannst. Auch wer den Flugpunkt in Moonglade noch nicht hat, nimmt diesen Weg und schaltet bei der Ankunft zuerst den Flugpunkt frei (48.10, 67.34). Unter neutralem Ruf wirst du angegriffen. Druiden können direkt Teleportieren: Moonglade nutzen; nach der Ankunft gehst du zum normalen Flugpunkt (48.10, 67.34) und schaltest ihn frei, damit du zurückfliegen kannst."}, [95]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [96]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [97]={npc="Orokai", tgt="Orokai"}, [98]={npc="Orokai", tgt="Orokai"}, [99]={hint="Sprecht mit Orokai, wenn Ihr bereit seid, herauszufinden, was er von dem schwach leuchtenden Ast in Erfahrung gebracht hat."}, [100]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [101]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [102]={desc="Flieg am normalen Flugpunkt in Moonglade ab (48.10, 67.34) und steig in Everlook aus, um die Kiste abzuholen."}, [103]={npc="Nami", tgt="Nami", desc="Die Batterien in der Kiste fallen nach etwa zwei Stunden aus; liefere sie direkt vom Flugpunkt aus an Kaylaena."}, [104]={desc="Reite vom Flugpunkt direkt nach Norden zu Kaylaenas Werkstatt und liefere zuerst die Kiste."}}},
    ["04-58"] = {danger={[1]="Ghansurok (Elite-Schimäre der Stufe 61) patrouilliert östlich des Shrine of Aviana; achte beim Kampf gegen Harpyien auf ihn."}, supply={[1]={}, [2]={}}, steps={[1]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Reite vom Flugpunkt direkt nach Norden zur Werkstatt und liefere zuerst die Kiste."}, [2]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [3]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Das Material liegt in den Überresten des Horde-Lagers in Dae'gun im Norden; nimm es mit, wenn du später vorbeikommst."}, [4]={npc="Ketharas", tgt="Ketharas", desc="Reite von der Werkstatt nach Südosten zurück zur Einsiedlerhöhle."}, [5]={npc="Ketharas", tgt="Ketharas"}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Himmelsfürst Omnuron", tgt="Himmelsfürst Omnuron", desc="Reite von der Einsiedlerhöhle nach Nordwesten zum Shrine of Aviana."}, [8]={npc="Himmelsfürst Omnuron", tgt="Himmelsfürst Omnuron"}, [9]={npc="Himmelsfürst Omnuron", tgt="Himmelsfürst Omnuron"}, [10]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={hint="Tötet 18 Wurmschwingenharpyien auf dem Hyjal und bringt ihre Federn zu Phoebe Highfeather."}, [13]={hint="Sammelt 8 angelaufene Hochfederarmreife von Nestern der Wurmschwingenharpyien."}, [14]={hint="Findet das Juwel des Horizonts in einem Nest der Harpyien der Wurmschwingen und bringt es zu Ketharas."}, [15]={hint="Tötet Zarrat Wurmschwinge und bringt Omnurons Speer zurück."}, [16]={npc="Verderbter Auswuchs", npcObj=true, desc="Klick mit rechts auf den Verderbten Auswuchs am Baum, um die Quest anzunehmen."}, [17]={hint="Findet und entfernt 6 verderbte Knoten von den Bäumen in der Nähe.", tag="Im Spiel prüfen"}, [18]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Himmelsfürst Omnuron", tgt="Himmelsfürst Omnuron"}, [22]={npc="Seltsame Krähe", tgt="Seltsame Krähe"}, [23]={npc="Seltsame Krähe", tgt="Seltsame Krähe", desc="Du kannst sie erst auf der Brücke in der Cradle of Tranquility im Norden erledigen, nimm sie also vorerst mit."}, [24]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring", desc="Folge dem Gebirgsfuß nach Westen."}, [25]={hint="Findet einen robusten Ast, mit dem Ihr Fenwick Togglespring erreicht."}, [26]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [27]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [28]={hint="Brecht den Ast, um Fenwick Togglespring zu befreien."}, [29]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [30]={npc="Fenwick Togglespring", tgt="Fenwick Togglespring"}, [31]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [32]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [33]={hint="Wartet, bis Ihr das persönliche Überlebenspaket sicher öffnen könnt"}, [34]={npc="Personal Survival Pack", tgt="Personal Survival Pack"}, [35]={npc="Brerufa", tgt="Brerufa"}, [36]={hint="Bezwingt 9 Höhlenwächter der Totenwaldfelle und kehrt zu Brerufa zurück."}, [37]={npc="Brerufa", tgt="Brerufa"}, [38]={npc="Brerufa", tgt="Brerufa", tag="Optional, Im Spiel prüfen", desc="Nimm sie nur an, wenn du sie sehen kannst. Gib sie nur ab, wenn du schon 8 Perlenketten hast; du musst nicht extra farmen."}, [39]={npc="Brerufa", tgt="Brerufa"}, [40]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [41]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [42]={hint="Sammelt 30 Bärenbeeren von Hyjal und kehrt zu Osi Mistpaw zurück."}, [43]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [44]={npc="Osi Mistpaw", tgt="Osi Mistpaw"}, [45]={hint="Findet und sprecht mit der Ältesten Mistpaw und dem Ältesten Pinespeaker innerhalb des Baus der Baumrindenfurbolgs."}, [46]={npc="Älteste Mistpaw", tgt="Älteste Mistpaw"}, [47]={npc="Älteste Mistpaw", tgt="Älteste Mistpaw"}, [48]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker"}, [49]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [50]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, Im Spiel prüfen", desc="Nimm sie nur an, wenn du sie sehen kannst (setzt Ruf bei der Rindenhöhle voraus)."}, [51]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, Im Spiel prüfen", desc="Nimm sie nur an, wenn du sie sehen kannst (setzt Ruf bei der Rindenhöhle voraus). Füll den Wasserschlauch am Teich vor dem Totenwaldbau."}, [52]={hint="Collect 10 Dried Hanging Herbs from around Barkskin Burrow and return them to Fennar Mossmane.", tag="Optional, Im Spiel prüfen"}, [53]={npc="Älteste Mistpaw", tgt="Älteste Mistpaw", tag="Optional, Im Spiel prüfen", desc="Nimm sie nur an, wenn du sie sehen kannst. Du kannst sie erst abgeben, wenn dein Ruf bei der Rindenhöhle neutral erreicht."}, [54]={hint="Beute von: Hyjaleule"}, [55]={hint="Sammelt 12 Klumpen Mondschleiermoos und kehrt zu Suma Mossmane zurück."}, [56]={hint="Tötet 8 Totemiker der Totenwaldfelle und 8 Teufelspfleger der Totenwaldfelle und kehrt zum Ältesten Pinespeaker zurück."}, [57]={hint="Fill a waterskin provided by Fennar Mossmane at the pond outside of the Deadwood Furbolg den.", tag="Optional, Im Spiel prüfen"}, [58]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch", tag="Im Spiel prüfen"}, [59]={hint="Beute von: Deadwood Warden"}, [60]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch", tag="Im Spiel prüfen"}, [61]={npc="Barkskin Matriarch", tgt="Barkskin Matriarch", tag="Im Spiel prüfen"}, [62]={hint="Escort the Barkskin Matriarch out of Deadwood Den and return to Barkskin Burrow.", tag="Im Spiel prüfen", desc="Eine Eskortenquest; in der Gruppe wartest du, bis alle sie angenommen haben, bevor ihr startet."}, [63]={npc="Brerufa", tgt="Brerufa"}, [64]={npc="Brerufa", tgt="Brerufa", tag="Optional, Im Spiel prüfen", desc="Gib sie nur ab, wenn du 8 Perlenketten hast."}, [65]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker"}, [66]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker"}, [67]={npc="Suma Mossmane", tgt="Suma Mossmane"}, [68]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, Im Spiel prüfen"}, [69]={npc="Fennar Mossmane", tgt="Fennar Mossmane", tag="Optional, Im Spiel prüfen"}, [70]={npc="Älteste Mistpaw", tgt="Älteste Mistpaw", tag="Optional, Im Spiel prüfen", desc="Gib sie nur ab, wenn dein Ruf neutral erreicht hat."}, [71]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker", tag="Optional, Im Spiel prüfen", desc="Nimm sie nur an, wenn du sie sehen kannst. Du kannst sie erst abgeben, wenn dein Ruf bei der Rindenhöhle freundlich erreicht."}, [72]={npc="Ältester Pinespeaker", tgt="Ältester Pinespeaker", tag="Optional, Im Spiel prüfen", desc="Gib sie nur ab, wenn dein Ruf freundlich erreicht hat. Hast du nicht genug, heb sie vorerst auf."}, [73]={npc="Eluneth", tgt="Eluneth", desc="Geh nach Norden."}, [74]={npc="Veteran des Dritten Krieges", tgt="Veteran des Dritten Krieges"}, [75]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [76]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [77]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [78]={npc="Mirt", tgt="Mirt"}, [79]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame", desc="Neben dem Gasthaus von Elderwild; die Eulennester liegen im Tal im Süden und lassen sich beim späteren Rückweg zu Eluneth einsammeln."}, [80]={hint="Fangt 6 entlaufene Schafe und bringt sie zurück."}, [81]={npc="Mirt", tgt="Mirt"}, [82]={npc="Geschmückte Waffenscheide", npcObj=true, desc="Der Aussichtspunkt westlich von Elderwild."}, [83]={npc="Geschmückte Waffenscheide", npcObj=true}, [84]={hint="Verwendet die geschmückte Waffenscheide, um mit dem Kriegsveteranen auf dem Aussichtspunkt in Holderwild zu sprechen und Euch seine Geschichte zu hören."}, [85]={npc="Veteran des Dritten Krieges", tgt="Veteran des Dritten Krieges"}, [86]={npc="Nicht gekennzeichnetes Grab", npcObj=true, desc="Am Straßenrand in Richtung Osten klickst du das Namenlose Grab mit rechts an, um die Quest anzunehmen."}, [87]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [88]={hint="Füllt Galvinquam Leafsyres Trinkflasche am Wasserfall ein Stück weiter den Weg hinauf.", tag="Im Spiel prüfen", desc="Füll mit der leeren Kalebasse aus der Quest am Wasserfall vor dir Wasser ab, nicht neben Galvinquam."}, [89]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre"}, [90]={npc="Galvinquam Leafsyre", tgt="Galvinquam Leafsyre", desc="Bring das Gepäck zum Summit of Eternity."}, [91]={npc="Lisbael Highfeather", tgt="Lisbael Highfeather", desc="Gib es danach am Shrine of Aviana ab."}, [92]={hint="Berührt das Krähenbildnis auf der Brücke über der Wiege der Ruhe, um die Wilde Göttin Jereman zu rufen."}, [93]={npc="Jereman", tgt="Jereman"}, [94]={npc="Jereman", tgt="Jereman"}, [95]={npc="Jereman", tgt="Jereman"}, [96]={npc="Jereman", tgt="Jereman"}, [97]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [98]={hint="Verscheucht die Stinktiere aus dem Bereich rund um Johuns Ausrüstung, ohne sie zu töten.", tag="Im Spiel prüfen"}, [99]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [100]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [101]={hint="Bringt 9 Schwänze eines Rostlaubfuchses zu Johun \"Haudrauf\" Dillas in Hyjal."}, [102]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [103]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [104]={npc="Kala'th", tgt="Kala'th", desc="Geh nach Westen."}, [105]={npc="Kala'th", tgt="Kala'th"}, [106]={hint="Bringt die Hirsche davon ab, sich wie Raubtiere aufzuführen."}, [107]={hint="Sucht in den ausgebrannten Gebäuden der Wiege der Ruhe nach 6 Metallklammern und 30 Nägeln und bringt sie Johun \"Haudrauf\" Dillis in Hyjal."}, [108]={npc="Kala'th", tgt="Kala'th"}, [109]={npc="Marrosis", tgt="Marrosis"}, [110]={npc="Marrosis", tgt="Marrosis"}, [111]={npc="Marrosis", tgt="Marrosis"}, [112]={hint="Eliminiert 3 vergessene Soldaten und 12 Fleischschinderräuber."}, [113]={hint="Durchsucht die Umgebung nach den fehlenden Grabinhalten."}, [114]={hint="Beschafft einen Tropfen gestohlenen Lebens von der Geißel in den Ruinen auf dem Hyjal und kehrt damit zu Ketharas zurück."}, [115]={hint="Setzt die Fackel des Überlebenden beim Knochenhaufen ein und sammelt dann das Amulett des Wiedererweckers ein."}, [116]={hint="Sammelt 20 sonnengebleichte Knochen."}, [117]={hint="Holt 8 Augen des Beobachters für Eluneth."}, [118]={npc="Marrosis", tgt="Marrosis"}, [119]={npc="Eluneth", tgt="Eluneth"}, [120]={hint="Geht nach Süden ins Tal und sammelt Federn aus den Nestern der Eulen.", tag="Im Spiel prüfen", desc="Ein kurzes Stück südlich von Eluneth; sie fallen auch von Hyjal-Eulen. Kehr nach dem Einsammeln nach Elderwild zurück."}, [121]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [122]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [123]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [124]={npc="Hnaz Blunderflame", tgt="Hnaz Blunderflame"}, [125]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [126]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [127]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [128]={npc="Daythor Brellan", tgt="Daythor Brellan"}, [129]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [130]={npc="Sefira Everbright", tgt="Sefira Everbright"}, [131]={npc="Daythor Brellan", tgt="Daythor Brellan"}}},
    ["04-60"] = {danger={[1]="Ghansurok (Elite-Schimäre der Stufe 61) streift über den Grat südlich von Kaylaenas Werkstatt.", [2]="Mazzogore der Schwache (Elite der Stufe 60) patrouilliert südlich von Dae'gun; umgeh ihn beim Kampf gegen Hunde.", [3]="Ve'han Talongrasp (Elite der Stufe 60) bewacht die Nordrassil-Hütte; komm bei den Kultistenquests nicht zu nah heran."}, grind={[1]={mob="Wachposten der Teufelswache", note="Die südliche Hälfte von Dae'gun; sammle nebenbei die verlassenen Vorräte und Horde-Trümmermaterialien auf."}, [2]={note="Das Kultistenlager östlich des Summit of Eternity; die Gipfelquests kämpfst du alle hier."}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="Geh auf der Straße zurück nach Osten."}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [4]={npc="Welkbart", tgt="Welkbart"}, [5]={npc="Yashiro", tgt="Yashiro"}, [6]={hint="Zündet die beiden Lagerfeuer in Dae'gun an und kehrt zu Yashiro zurück."}, [7]={text="Entzünde das Lagerfeuer im Südosten, geh weiter nach Südosten zu Renalard; gib zuerst „Kluges Wesen\" ab, nimm die Asche- und die Fuchsquest an und säubere auf dem Rückweg Dae'gun noch einmal.", tag="Im Spiel prüfen"}, [8]={npc="Renalard", tgt="Renalard"}, [9]={npc="Renalard", tgt="Renalard"}, [10]={npc="Renalard", tgt="Renalard"}, [11]={hint="Sammelt 8 zurückgelassene Ausrüstungsgegenstände.", desc="Lock den Dämon mit dem Büschel Fuchsfell (Tuft of Fox Fur) aus der Quest weg und sammle dann 8 verlassene Vorräte auf. Die Vorräte liegen nicht neben Renalard."}, [12]={hint="Plündert die Überreste der Hordebasis und bringt 5 Stücke ausgefranster Draht, 5 Stücke Metallschrott und 5 verkalkte Exkremente zu Kaylaena."}, [13]={hint="Beschafft 6 ephemere Essenzen für Elaena Moonwhisper."}, [14]={hint="Tötet 12 Teufelswächter in Dae'gun."}, [15]={hint="Holt eine Prise von Azgalors Asche aus den Ruinen von Dae'gun auf dem Hyjal."}, [16]={hint="Betretet Dae'gun, findet einen Aussichtspunkt und erstattet dann Johun einen detaillierten Bericht.", tag="Im Spiel prüfen"}, [17]={npc="Yashiro", tgt="Yashiro", desc="Kehr nach dem Säubern von Dae'gun zur Abgabe zu Yashiro zurück."}, [18]={npc="Yashiro", tgt="Yashiro"}, [19]={hint="Kämpft Euch zusammen mit Yashiro einen Weg durch Dae'gun frei.", tag="Im Spiel prüfen", desc="Folge Yashiro, der den Weg freiräumt; sie ist abgeschlossen, wenn du am Ende Verdammniswache Xarkul (Doomguard Xarkul) besiegst."}, [20]={npc="Yashiro", tgt="Yashiro", tag="Im Spiel prüfen", desc="Gib sie bei Yashiro dort ab, wo das Ereignis endet; das ist nicht unbedingt der Ausgangspunkt."}, [21]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [22]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Gruppe empfohlen, Optional", desc="Beide Ziele sind Elite-Dämonen der Stufe 60. Ohne Gruppe überspring die Schritte \"Das Böse auslaugen\"-\"Vogelfluglinie\", \"Vogelfluglinie\"."}, [23]={hint="Benutzt das Auge des unendlichen Einflusses, um Bethra'zel und Mazzogore die Macht zu entziehen und sie dann zu töten.", tag="Gruppe empfohlen, Optional"}, [24]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Gruppe empfohlen, Optional"}, [25]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Gruppe empfohlen, Optional"}, [26]={npc="Welkbart", tgt="Welkbart"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="Renalard", tgt="Renalard", desc="Geh nach Südosten."}, [29]={nodeA="{a:16849}", tag="Im Spiel prüfen", desc="Geh von Renalard ein kurzes Stück den Berg nach Osten hinauf und schalte den Flugpunkt bei Fayran Elthas frei. Gib zuerst die paar Quests ab, die du auf den Berg mitgebracht hast, um dein Questlog zu entlasten."}, [30]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [31]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne", tag="Optional"}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="Sebelia", tgt="Sebelia", desc="Gib das Briefpaket gleich in Everlook ab und mach dann die Postkette."}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Im Spiel prüfen", desc="Geh vom Summit of Eternity nach Westen den Berg hinunter an Renalard vorbei und dann nach Süden zur Werkstatt. Ist der Bergpfad nicht passierbar, flieg zu den Tainted Foothills und reite nach Norden."}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [36]={hint="Dreht die Getriebe und verbindet die Batterieanschlüsse an beiden Seiten von Kaylaenas Glevenschleuder."}, [37]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [38]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Gruppe empfohlen, Optional", desc="Der angelockte Ghansurok ist eine Elite-Schimäre der Stufe 61."}, [39]={hint="Geht zum Kamm südlich von Kaylaenas Werkstatt und findet einen Weg, ein ablenkendes Getöse zu machen, um die Schimäre Ghansurok so nah anzulocken, dass sie angegriffen werden kann.", tag="Gruppe empfohlen, Optional", desc="Interagiere mit der Trommel an der Klippe südlich der Werkstatt und lock die Schimäre in die Reichweite des Klingenradwerfers, damit der NSC ihn bedient; zieh sie nicht weit weg, um sie mit Gewalt zu bekämpfen."}, [40]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Gruppe empfohlen, Optional"}, [41]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather", desc="Geh von der Werkstatt ein kurzes Stück nach Südwesten zum Shrine of Aviana."}, [42]={npc="Ketharas", tgt="Ketharas", desc="Reite vom Schrein nach Südosten zurück zur Einsiedlerhöhle."}, [43]={npc="Ketharas", tgt="Ketharas"}, [44]={npc="Ketharas", tgt="Ketharas"}, [45]={npc="Ketharas", tgt="Ketharas"}, [46]={desc="Reite von der Einsiedlerhöhle nach Westen und flieg am Flugpunkt der Tainted Foothills ab."}, [47]={npc="Gastwirt Vizzie", tgt="Gastwirt Vizzie"}, [48]={npc="Gastwirt Vizzie", tgt="Gastwirt Vizzie"}, [49]={hint="Findet 4 vermisste Post in den Hügeln nördlich von Everlook und bringt sie zurück zu Gastwirt Vizzie.", tag="Im Spiel prüfen"}, [50]={npc="Gastwirt Vizzie", tgt="Gastwirt Vizzie"}, [51]={npc="Gastwirt Vizzie", tgt="Gastwirt Vizzie", desc="Bring die Post zurück zum Gipfel des Hyjal und gib sie dort ab."}, [52]={desc="Du steigst an den Tainted Foothills um."}, [53]={npc="Sebelia", tgt="Sebelia", tag="Im Spiel prüfen"}, [54]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [55]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [56]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [57]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [58]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [59]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow", tag="Gruppe empfohlen, Optional"}, [61]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [62]={hint="Findet Dornensamen in den Wäldern am Gipfel von Hyjal und bringt sie zu Tiala Whitemane zurück."}, [63]={hint="Aktiviert die Wächtersteine im Norden, Westen und Süden rund um die Blackthorne-Kultisten.", tag="Im Spiel prüfen", desc="Der nördliche, westliche und südliche Stein zählen jeweils als ein Ziel; du musst alle drei aufsuchen."}, [64]={hint="Setzt den Stab des Berges gegen 10 Mitglieder des Schwarzdornpakts auf dem Gipfel der Ewigkeit ein, um ihre Schutzzauber zu entfernen und sie anschließend zu töten.", desc="Dieselben Kultisten zählen auch für „Den Wahn beenden\" und „Verdrehte Werkzeuge\"; setz zuerst den Stab ein, töte sie dann, und mach alle drei zusammen."}, [65]={hint="Tötet 10 Adepten der Blackthorne und 10 wildnisgezeichnete Kultisten."}, [66]={hint="Beschafft einen tückischen Ritualistenkris und einen zurückspringenden Knorrenborkenstab von den Blackthorne-Kultisten."}, [67]={hint="Sammelt 5 große Hippogryphenfedern und 3 öliges Schimärenhaar für Marn"}, [68]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [69]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [70]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [71]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [72]={hint="Pflanzt Dornensamen in der Nähe des Gasthauses, des Lagerturms und der Baumgruppe im Lager der loyalistischen Druiden.", tag="Im Spiel prüfen"}, [73]={npc="Tiala Weißmähne", tgt="Tiala Weißmähne"}, [74]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [75]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="Geh nach der Annahme zuerst zu Marn Euhorn, um „Winde der Läuterung\" abzugeben und „Archimondes Begnadigung\" (Archimonde's Pardon) anzunehmen; mach beide auf demselben Weg."}, [76]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [77]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [78]={hint="Verwendet den verzauberten Zweig, um 5 Irrwische in der Nähe von Nordrassil zu befreien.", tag="Im Spiel prüfen", desc="Befreie das Irrlicht, das schon unter den Wurzeln steckt, und beschwöre es nicht mit einem Gegenstand auf der Lichtung. Mach sie auf demselben Weg wie „Archimondes Begnadigung\"."}, [79]={hint="Nehmt Marns Räucherwerk und lasst den Rauch die Luft um Archimondes Überreste reinigen", tag="Im Spiel prüfen"}, [80]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [81]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [82]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [83]={desc="Du steigst an den Tainted Foothills und in Everlook um."}, [84]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [85]={npc="Erelas Ambersky", tgt="Erelas Ambersky"}, [86]={text="Geh in Rut'theran durch das Portal nach Darnassus."}, [87]={npc="Erzdruide Fandral Staghelm", tgt="Erzdruide Fandral Staghelm"}, [88]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}}},
    ["04-59"] = {name="Westliche Pestländer", steps={[1]={bindA="{a:348}", desc="Nutze den Ruhestein nur, wenn er noch an Aerie Peak gebunden und einsatzbereit ist. Sonst nimm die Schiffsroute als Ausweichplan: Geh durch das Portal zurück nach Rut'theran, flieg nach Auberdine, nimm das Schiff nach Menethil, steig in Southshore aus und flieg dann zum Lager Chillwind."}, [2]={desc="Überspring das, wenn du schon im Lager Chillwind bist. Fehlt das Lager Chillwind auf der Flugkarte, geh von Aerie Peak auf dem Bergweg nach Norden in die Westliche Pestländer und dann nach Westen zum Lager Chillwind."}, [3]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [4]={npc="Flint Shadowmore", tgt="Flint Shadowmore", tag="Optional"}, [5]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [6]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [7]={npc="Marlene Redpath", tgt="Marlene Redpath"}, [8]={hint="Bringt Josephs Ehering zu Chromie."}, [9]={npc="Chromie", tgt="Chromie"}, [10]={npc="Chromie", tgt="Chromie"}, [11]={npc="Chromie", tgt="Chromie"}, [12]={hint="Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal."}, [13]={hint="Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren."}, [14]={npc="Chromie", tgt="Chromie"}, [15]={npc="Chromie", tgt="Chromie"}, [16]={npc="Chromie", tgt="Chromie"}, [17]={desc="Andorhal hat keinen Flugpunkt. Geh zuerst nach Süden zurück zur Chillwindspitze und flieg von dort."}, [18]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [19]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [20]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [21]={hint="Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt."}, [22]={hint="Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe."}, [23]={npc="Aurora Skycaller", tgt="Aurora Skycaller"}, [24]={hint="Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Nathaniel Dumah am Chillwindposten in den Westlichen Pestländern zurück."}, [25]={hint="Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [26]={npc="Erdhaufen", npcObj=true}, [27]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [28]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [29]={hint="Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath."}, [30]={hint="Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet."}, [31]={npc="Geißelkessel", npcObj=true}, [32]={npc="Geißelkessel", npcObj=true}, [33]={npc="Grafiker Renfray", tgt="Grafiker Renfray"}, [34]={npc="Hohepriesterin MacDonnell", tgt="Hohepriesterin MacDonnell"}, [35]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [36]={npc="Kommandant Ashlam Valorfist", tgt="Kommandant Ashlam Valorfist"}, [37]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [38]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [39]={npc="Termitenfass", npcObj=true}, [40]={npc="Termitenfass", npcObj=true}, [41]={hint="Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Nathaniel Dumah im Chillwind-Posten in den westlichen Pestländern zurück."}, [42]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [43]={hint="Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt."}, [44]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [45]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [46]={hint="Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt."}, [47]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [48]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [49]={hint="Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück.", tag="Im Spiel prüfen", desc="Die Koordinaten sind ungefähr. Am Eingang und am Turm stehen Wachen des Scharlachroten Kreuzzugs; zieh sie einzeln."}, [50]={npc="Kirsta Deepshadow", tgt="Kirsta Deepshadow"}, [51]={npc="Nathaniel Dumah", tgt="Nathaniel Dumah"}, [52]={desc="In der Nähe gibt es keinen Flugpunkt: Geh nach Süden zurück zur Chillwindspitze und flieg von dort, oder geh nach Osten über den Thondroril und reite durch die Östlichen Pestländer zur Kapelle."}, [53]={npc="Carlin Redpath", tgt="Carlin Redpath", tag="Optional"}, [54]={npc="Carlin Redpath", tgt="Carlin Redpath"}, [56]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus"}, [58]={npc="Königlicher Disponent Bathrilor", tgt="Königlicher Disponent Bathrilor"}, [59]={npc="Königlicher Disponent Bathrilor", tgt="Königlicher Disponent Bathrilor"}, [60]={npc="Alte Emma", tgt="Alte Emma"}, [61]={tag="Optional", desc="Geh nur nach Lakeshire, wenn du Den wahren Meister (Die wahren Meister) hast; sonst überspring die Schritte 61-63 und flieg direkt von Sturmwind zur Morgan's Vigil."}, [62]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Optional"}, [63]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Optional"}, [65]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [66]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [67]={hint="Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt."}, [68]={npc="Oralius", tgt="Oralius", tag="Optional"}, [69]={hint="Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen.", tag="Optional", desc="Eigener Umweg, in der Nähe gibt es keine anderen Ziele. Wenn du es eilig hast, überspring es."}, [70]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [71]={npc="Oralius", tgt="Oralius", tag="Optional"}, [72]={text="Noch nicht Stufe 60? Lauf einmal die Schwarzfelstiefen. Reicht das nicht, farm Stratholme oder Scholomance."}}},
    ["05-d13"] = {name="Stratholme", entrance="Östliche Pestländer 26.52, 10.36", steps={[2]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [3]={hint="Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", tag="Dungeon-Vorquest"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [5]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [6]={hint="Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", tag="Dungeon-Vorquest"}, [7]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [9]={hint="Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", tag="Dungeon-Vorquest"}, [10]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [12]={hint="Hört Euch an, was Tirion Fordring zu sagen hat.", tag="Dungeon-Vorquest"}, [13]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [14]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [15]={hint="Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", tag="Dungeon-Vorquest"}, [16]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [17]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [18]={hint="Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", tag="Dungeon-Vorquest"}, [19]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Dungeon-Vorquest"}, [21]={npc="Grafiker Renfray", tgt="Grafiker Renfray", tag="Dungeon-Vorquest"}, [22]={npc="Grafiker Renfray", tgt="Grafiker Renfray"}, [23]={text="Geh vom Lager Chillwind nach Osten durch die Westliche Pestländer in die Östliche Pestländer und folge der Straße nach Norden bis Stratholme.", tag="Im Spiel prüfen"}, [24]={text="Eingang: Stratholme"}, [25]={text="Verlass Stratholme und geh nach Südosten zur Kapelle des Hoffnungsvollen Lichts.", tag="Im Spiel prüfen"}}},
    ["05-d12"] = {name="Blackrock Depths", nameA="{a:1584}", entrance="Sengende Schlucht 34.80, 85.30", pickup="Nimm Kharan Mighthammer an, sobald du Die glimmenden Ruinen von Thaurissan in Eisenschmiede abgegeben hast. Die Quests der Brennenden Steppe nimmst du in der Gegend von Morgans Wacht an.", pickupS={{"Nimm Kharan Mighthammer an, sobald du Die glimmenden Ruinen von Thaurissan in Eisenschmiede abgegeben hast"}, {"Die Quests der Brennenden Steppe nimmst du in der Gegend von Morgans Wacht an"}}, steps={[1]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus", tag="Dungeon-Vorquest"}, [2]={hint="Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.", tag="Dungeon-Vorquest"}, [3]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus", tag="Dungeon-Vorquest"}, [4]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus", tag="Dungeon-Vorquest"}, [5]={hint="Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.", tag="Dungeon-Vorquest"}, [6]={npc="Königliche Historikerin Archesonus", tgt="Königliche Historikerin Archesonus", tag="Dungeon-Vorquest"}, [7]={npc="König Magni Bronzebeard", tgt="König Magni Bronzebeard", desc="Die Voraussetzung ist Ruinen von Thaurissan (Die glimmenden Ruinen von Thaurissan); nimm sie an, nachdem du in Station 59 von Kapitel 04 in Eisenschmiede abgegeben hast."}, [8]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu", tag="Optional", desc="Gib sie erst ab, wenn du sie in den Verwüsteten Landen angenommen hast."}, [9]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu", tag="Optional", desc="Kharanos liegt nicht auf dem Weg; überspring es, wenn du den Umweg nicht machen willst."}, [10]={npc="Oralius", tgt="Oralius"}, [11]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [12]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [13]={hint="Lasst Velarok Windblade seine Geschichte erzählen.", tag="Dungeon-Vorquest"}, [14]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [15]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [16]={hint="Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade.", tag="Dungeon-Vorquest"}, [17]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [18]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [19]={hint="Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade.", tag="Dungeon-Vorquest"}, [20]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [21]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [22]={hint="Bringt ein Symbol von Ragnaros zu Velarok Windblade.", tag="Dungeon-Vorquest"}, [23]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [24]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [25]={hint="Wartet bis Velarok Windblade die Fackel der Vergeltung vollendet hat.", tag="Dungeon-Vorquest"}, [26]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [27]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [28]={npc="Fackel der Vergeltung", npcObj=true, tag="Dungeon-Vorquest"}, [29]={npc="Kalaran Windblade", tgt="Kalaran Windblade", tag="Dungeon-Vorquest"}, [30]={npc="Knappe Maltrake", tgt="Knappe Maltrake", tag="Dungeon-Vorquest"}, [31]={npc="Knappe Maltrake", tgt="Knappe Maltrake", tag="Dungeon-Vorquest"}, [32]={hint="Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", tag="Dungeon-Vorquest"}, [33]={npc="Knappe Maltrake", tgt="Knappe Maltrake", tag="Dungeon-Vorquest"}, [34]={npc="Hort des Schwarzdrachenschwarms", npcObj=true, tag="Dungeon-Vorquest"}, [35]={npc="Hort des Schwarzdrachenschwarms", npcObj=true, tag="Dungeon-Vorquest"}, [36]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Dungeon-Vorquest"}, [37]={hint="Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Kalaran Windblade erhalten habt.", tag="Dungeon-Vorquest"}, [38]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous", tag="Dungeon-Vorquest"}, [39]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [40]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Dungeon-Vorquest"}, [41]={hint="Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.", tag="Dungeon-Vorquest"}, [42]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Dungeon-Vorquest"}, [43]={npc="Helendis Riverhorn", tgt="Helendis Riverhorn", tag="Dungeon-Vorquest"}, [44]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Dungeon-Vorquest"}, [45]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Dungeon-Vorquest"}, [46]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Dungeon-Vorquest"}, [47]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Dungeon-Vorquest"}, [48]={hint="Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.", tag="Dungeon-Vorquest"}, [49]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Dungeon-Vorquest"}, [50]={npc="Hochlord Bolvar Fordragon", tgt="Hochlord Bolvar Fordragon", tag="Dungeon-Vorquest"}, [51]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Dungeon-Vorquest"}, [52]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Dungeon-Vorquest"}, [53]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Dungeon-Vorquest"}, [54]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Dungeon-Vorquest"}, [55]={hint="Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.", tag="Dungeon-Vorquest"}, [56]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Dungeon-Vorquest"}, [57]={npc="Marshal Maxwell", tgt="Marshal Maxwell", tag="Optional"}, [58]={text="Folge von Morgan's Vigil der Straße durch die Brennende Steppe nach Westen in den Schwarzfels."}, [59]={text="Eingang: Blackrock Depths"}, [60]={npc="Kharan Mighthammer", tgt="Kharan Mighthammer"}, [61]={hint="Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept.", tag="Optional"}, [62]={hint="Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen."}, [63]={hint="Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe."}, [64]={hint="Begebt Euch in die Blackrocktiefen und tötet Bael'Gar."}, [65]={npc="Marshal Windsor", tgt="Marshal Windsor", tag="Optional"}, [66]={npc="Oralius", tgt="Oralius"}, [67]={npc="Maxwort Uberglint", tgt="Maxwort Uberglint"}, [68]={npc="Cyrus Therepentous", tgt="Cyrus Therepentous"}, [69]={npc="Ragnar Donnerbräu", tgt="Ragnar Donnerbräu", tag="Optional"}}},
  },
  quests = {
    [5] = {n="Jitters' knurrender Magen", d="Sprecht mit Küchenchef Grual."},
    [6] = {n="Kopfgeld auf Garrick Padfoot", d="Tötet Garrick Padfoot und bringt seinen Kopf zu Deputy Willem in der Nähe der Abtei von Nordhain.", tgo={{"Garrick Padfoot"}}},
    [7] = {n="Säuberung im Koboldlager", d="Tötet 10 von dem Koboldgezücht und kehrt dann zu Marshal McBride zurück.", tgo={{"Koboldgezücht"}}},
    [9] = {n="Tod auf den Feldern", d="Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet.", tgo={{"Erntebehüter"}}},
    [10] = {n="Die Erlösung von Scrimshank", d="Erforscht das Schicksal von Unterfeldmesser Scrimshank und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Fizzledowser.", objs={"Scrimshanks Feldmesser-Ausstattung"}},
    [12] = {n="Die Volksmiliz", d="Gryan Stoutmantle möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", tgo={{"Fallensteller der Defias"}, {"Schmugglerin der Defias"}}},
    [13] = {n="Die Volksmiliz", d="Gryan Stoutmantle möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", tgo={{"Plünderin der Defias"}, {"Ausplünderer der Defias"}}},
    [15] = {n="Überprüfung der Echokammmine", d="Tötet 10 Koboldtagelöhner und erstattet dann Marshal McBride Euren Bericht.", tgo={{"Koboldtagelöhner"}}},
    [17] = {n="Reagenzsuche in Uldaman", d="Bringt zwölf magenta Funguskappen nach Thelsamar zu Ghak Healtouch.", objs={"Magenta Kappengruppen"}},
    [18] = {n="Bruderschaft der Diebe", d="Bringt 12 rote Sackleinenkopftücher zu Deputy Willem in der Nähe der Abtei von Nordhain.", tgo={{"Rohling der Defias"}}},
    [19] = {n="Tharil'zun", d="Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marshal Marris.", tgo={{"Tharil'zun"}}},
    [20] = {n="Bedrohung durch die Blackrock", d="Bringt 10 kampferprobte Äxte nach Seenhain zu Marshal Marris.", tgo={{"Held der Blackrock", "Schattenzauberer der Blackrock", "Renegat der Blackrock", "Grunzer der Blackrock", "Kundschafter der Blackrock", "Fährtenleser der Blackrock", "Späher der Blackrock", "Wachposten der Blackrock"}}},
    [21] = {n="Scharmützel in der Echokammmine", d="Tötet 12 Koboldhilfsarbeiter und kehrt dann zu Marshal McBride in der Abtei von Nordhain zurück.", tgo={{"Koboldhilfsarbeiter"}}},
    [26] = {n="Eine wertvolle Lektion", d="Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade."},
    [29] = {n="Prüfung des Sees", d="Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", objs={"Der Schrein von Remulos"}},
    [33] = {n="Wölfe an der Grenze", d="Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch.", tgo={{"Wilder Waldwolf", "Junger Wolf", "Struppiger Waldwolf", "Struppiger junger Wolf", "TEST WOLF (ALPHA FIRST)", "TEST WOLF (ALPHA SECOND)"}}},
    [34] = {n="Ein ungebetener Gast", d="Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis.", tgo={{"Stopfwanst"}}},
