    [2201] = {n="Suche nach den Edelsteinen", d="Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.", tgo={{}, {"Grimlok"}, {}}, objs={"Schattenschmiedecache", "Verdächtige Urne"}},
    [2204] = {n="Restaurierung der Halskette", d="Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab.", tgo={{"Archaedas"}}},
